export type FaqP0Lang = "es" | "pt" | "fr" | "tr" | "hi" | "zh";

export const faqP0Translations: Record<FaqP0Lang, Record<string, { q: string; a: string }>> = {
  es: {
    "What is CryptoOwnBank?": { q: "¿Qué es CryptoOwnBank?", a: "CryptoOwnBank es donde todo empieza — y no termina. Sé dueño de tu cripto, gestionala desde una sola interfaz y quédate con todos tus ingresos. Todo el trabajo se hace por ti: el Recommendations Hub muestra rendimientos que te perderías, Statement Insights compara las tasas de tu banco con las on-chain, los informes fiscales se generan automáticamente y la información llega a ti. Sigue tu portafolio en más de 32 blockchains, gana 5–8% de rendimiento fijo en RLUSD, opera en DEXs nativos, envía pagos globalmente — tus claves permanecen en tus manos. Elige tu seguridad: cold wallet, hot wallet, firma con hardware o teléfono. Si alguna vez te vas, tu cripto sigue en tu wallet. Y el Legacy Plan asegura que tu cripto pase a tu familia si algo te ocurre — así que realmente no termina. Ya seas unbanked, debanked o simplemente estés cansado de confiar en plataformas que pueden fallar — CryptoOwnBank te da las herramientas para ser tu propio banco." },
    "Why was CryptoOwnBank created? (And why should I use it?)": { q: "¿Por qué se creó CryptoOwnBank? (¿Y por qué debería usarlo?)", a: "CryptoOwnBank se creó porque los exchanges pueden fallar, congelar fondos o quebrar — y cuando lo hacen, tu dinero queda atrapado. FTX. Celsius. Voyager. Mt. Gox. La gente confió en plataformas con miles de millones, y esas plataformas fallaron. CryptoOwnBank existe para que tu cripto nunca esté en manos de nadie más. Lo construimos para resolver cinco problemas: (1) Propiedad plena — tu wallet permanece bajo tu control. Nunca vemos ni almacenamos tus claves privadas. Incluso si dejas CryptoOwnBank, tu cripto permanece en tu wallet. Nunca quedas atrapado. (2) Rendimientos reales que te quedas — gana 5–8% APR fijo en RLUSD a través de Soil Protocol, quédate con cada centavo. Sin comisiones de plataforma, sin intermediarios. (3) Seguridad en tus términos — cold wallet, hot wallet, firma con hardware o teléfono. Tú eliges. Ningún tercero desinteresado en tu proceso de decisión. (4) Todo el trabajo se hace por ti — el Recommendations Hub muestra rendimientos que te perderías, Statement Insights compara las tasas de tu banco con las on-chain, y la información llega a ti en lugar de que tengas que buscarla. (5) Piensa en valor, no en precio en USD — el dólar pierde poder adquisitivo cada año, pero un XRP es un XRP sin importar en cuyas manos esté. Te ayudamos a ver lo que tu cripto puede hacer, no solo lo que 'vale' en una moneda que se encoge. Aquí es donde todo empieza. Y no termina — el Legacy Plan (interruptor de hombre muerto) asegura que tu cripto pase a tu familia si algo te ocurre. No a un exchange. No a un tribunal de quiebras. A las personas que elegiste." },
    "Is this a wallet? Do you hold my funds?": { q: "¿Esto es un wallet? ¿Custodian mis fondos?", a: "No — somos 100% no custodiales. Nunca retenemos, controlamos ni tenemos acceso a tus fondos o claves privadas. Todas las acciones de vault (depósitos, retiros) se firman directamente desde tu propio wallet — cold o hot, tú eliges. Para el seguimiento del portafolio, solo leemos datos públicos on-chain. Aquí está la clave: incluso si CryptoOwnBank desapareciera mañana, tu cripto estaría exactamente donde está ahora — en tu wallet. Puedes irte en cualquier momento y seguir teniendo control y acceso total a todo. Somos una herramienta que trabaja para ti, no una plataforma que custodia tus activos." },
    "Is this safe? Do you hold my funds?": { q: "¿Es seguro? ¿Custodian mis fondos?", a: "No — CryptoOwnBank es 100% no custodial. Nunca retenemos, controlamos ni tenemos acceso a tus fondos o claves privadas. Cada transacción (cambios de trustline, órdenes DEX, pagos) se construye en tu navegador y se firma en tu cold wallet (Ledger o Xumm/Xaman). Solo leemos tu dirección pública para mostrar saldos y preparar transacciones sin firmar para que las apruebes. Hay cero riesgo de plataforma — incluso si CryptoOwnBank desapareciera mañana, tus fondos permanecen seguros en tu wallet en la blockchain XRPL." },
    "Do you ever have access to my crypto? What if CryptoOwnBank shuts down?": { q: "¿Alguna vez tienen acceso a mi cripto? ¿Qué pasa si CryptoOwnBank cierra?", a: "No — en ningún momento tenemos acceso a tu cripto. Somos 100% no custodiales. Nunca vemos tus claves privadas, nunca retenemos tus fondos y nunca tenemos la capacidad de mover tus activos. Cada depósito en vault, retiro, operación y pago lo firmas tú en tu propio dispositivo. Esta es la diferencia fundamental entre CryptoOwnBank y los servicios custodiales: si una firma de custodia cierra, estás en una fila de acreedores esperando recuperar tus activos (pregunta a cualquier cliente de FTX). Si CryptoOwnBank cerrara mañana, tu cripto no se vería afectada en absoluto. Tus fondos viven en la blockchain en tu wallet, no en nuestros servidores. Podrías seguir usando tu cold wallet con cualquier otra app compatible con XRPL, acceder a tus posiciones de Soil vault directamente a través de Soil Protocol y ver tus saldos en cualquier explorador de blockchain. Somos una capa de herramientas sobre tu autocustodia — no un custodio." },
    "Does CryptoOwnBank control my money or make decisions for me?": { q: "¿CryptoOwnBank controla mi dinero o toma decisiones por mí?", a: "No. Estamos construidos en torno a una idea simple: nosotros lo traemos todo a la mesa, y tú eres el único que dice sí. Esto es lo que significa en la práctica — (1) Somos la mesa: todo lo que necesitas para configurar, revisar y actuar está reunido en un solo lugar. (2) Somos el explicador: te decimos en palabras claras qué hace cada paso antes de que lo hagas. (3) Somos la lista de verificación y el rastreador: nos aseguramos de que nada que deba hacerse se omita, y puedes seguir el progreso después. (4) Tú eres el único que dice sí: nada ocurre hasta que lo apruebas con tu propio wallet. Nunca retenemos tu dinero, tus claves ni tu frase de recuperación, y nunca decidimos con quién se te permite tratar. No intentamos engancharnos a todos y a todo — el poder permanece contigo y con la tecnología, no con nosotros. Esa es la diferencia entre una herramienta que trabaja para ti y una empresa que trabaja sobre ti." },
    "Is CryptoOwnBank a bank, broker, or trust company?": { q: "¿CryptoOwnBank es un banco, un bróker o una compañía fiduciaria?", a: "No. CryptoOwnBank es software no custodial — un panel y una capa de herramientas para wallets de autocustodia y protocolos on-chain. No somos un banco, bróker-dealer, transmisor de dinero ni compañía fiduciaria (trust company). No retenemos tus activos, no garantizamos rendimientos de inversión ni actuamos como fiduciario ni abogado de sucesiones. Las cifras de rendimiento que ves (por ejemplo, los APR de Soil vault) provienen de protocolos de terceros y no están garantizadas por CryptoOwnBank. El Legacy Plan almacena instrucciones de recuperación cifradas que tú escribes — no es un testamento legal, un instrumento fiduciario ni un servicio custodial de herencia." },
    "What is the Legacy Plan (dead-man switch)?": { q: "¿Qué es el Legacy Plan (interruptor de hombre muerto)?", a: "El Legacy Plan protege tu cripto después de que fallezcas — o si quedas incapacitado. Está disponible como complemento independiente por <strong>$29/yr</strong> en cualquier nivel, o <strong>incluido gratis con Pro</strong> ($99/mo). Es un interruptor de hombre muerto: haces check-in en un horario que eliges (semanal, quincenal, mensual o trimestral). Si fallas un check-in, comienza un período de gracia. Durante el período de gracia, se notifica a tu contacto secundario (cónyuge, abogado, etc.) para verificar tu estado. Si el período de gracia expira sin respuesta, tus beneficiarios reciben las instrucciones de recuperación del wallet que configuraste — dónde está guardado tu hardware wallet, dónde está la copia de la seed phrase, cómo acceder a un setup CypheRock 2-of-5 Shamir, etc.<br/><br/><strong>Lo que NUNCA almacenamos:</strong> seed phrases, claves privadas, contraseñas o PINs. Solo almacenamos TUS instrucciones sobre <em>dónde</em> están esas cosas — 'placa de acero en la caja fuerte ignífuga' o 'Tarjeta 1 con el abogado, Tarjeta 3 en caja de seguridad del banco.' Todo está cifrado en reposo y se entrega solo cuando se activa el interruptor. Member for Life — tu cripto no muere contigo." },
    "How does the Legacy Plan check-in work?": { q: "¿Cómo funciona el check-in del Legacy Plan?", a: "Presionas el botón 'I'm Still Here' en el panel de tu Legacy Plan. Eso es todo — un clic reinicia tu temporizador. Tú eliges la frecuencia: semanal, quincenal, mensual (recomendado) o trimestral. Si fallas un check-in, el sistema entra en un período de gracia (14 días por defecto, configurable hasta 90 días). Durante la gracia, se notifica a tu contacto secundario para que intente contactarte. Si aún no haces check-in al final del período de gracia, el sistema se activa y tus beneficiarios reciben sus instrucciones. Puedes hacer check-in en cualquier momento — incluso durante el período de gracia — para restablecer todo a la normalidad." },
    "Is the Legacy Plan really 'Member for Life'?": { q: "¿El Legacy Plan es realmente 'Member for Life'?", a: "Sí — y tienes tres formas de pagarlo: <strong>$29/yr</strong>, <strong>$99/5yr</strong>, o <strong>$499 once for life</strong>. El nivel Pro ($99/mo o $799/yr) incluye Legacy Plan gratis. Cualquiera que elijas, el temporizador de check-in sigue corriendo, tus instrucciones de beneficiarios permanecen cifradas y listas, y el interruptor de hombre muerto siempre está armado. Si una suscripción mensual o anual caduca, el plan se pausa (no se elimina) — tus datos se conservan para que puedas reanudarlo en cualquier momento. La opción de por vida es la que la mayoría de los miembros acaba eligiendo cuando se dan cuenta de que el punto del estate planning es que debe sobrevivir a la caducidad de una tarjeta, el cierre de un banco o una renovación olvidada." },
    "What is Split Delivery for the Legacy Plan?": { q: "¿Qué es Split Delivery para el Legacy Plan?", a: "Split delivery es como multi-sig para el correo — en lugar de que un beneficiario reciba todas las instrucciones de recuperación del wallet, divides la información entre varias personas para que deban colaborar. Por ejemplo, la Persona A recibe 'el Ledger está en la caja fuerte de la oficina en casa' y la Persona B recibe 'la placa de acero de la seed phrase está en la caja de seguridad del banco #42.' Ninguna persona sola puede acceder al wallet.<br/><br/>Puedes elegir <strong>All Required</strong> (se necesita la pieza de cada beneficiario) o <strong>Threshold</strong> (M-of-N, como Shamir — p. ej. cualesquiera 2-of-3 beneficiarios pueden reconstruir las instrucciones completas). Esto combina perfectamente con el sistema de tarjetas 2-of-5 de CypheRock — da ubicaciones de tarjetas diferentes a diferentes beneficiarios. Ningún competidor ofrece división a nivel de entrega como esta. Actívalo con un interruptor en el panel de tu Legacy Plan." },
    "What is the Legacy Plan Lifetime ($499 one-time)?": { q: "¿Qué es el Legacy Plan Lifetime ($499 one-time)?", a: "Legacy Plan Lifetime es un pago único de $499 (o ~$449 en cripto con nuestro 10% de descuento on-chain) que te da el Legacy Plan para siempre — sin cargos recurrentes, sin fallos por tarjeta caducada, sin riesgo de que una suscripción olvidada haga caducar el plan exactamente cuando más se necesita. El Lifetime te cubre mientras estés vivo Y durante 12 meses después de que se active tu interruptor de hombre muerto y se liberen las instrucciones de recuperación a tus beneficiarios. Ese año extra existe para que tus sobrevivientes tengan tiempo de usar realmente el sistema — leer los correos, combinar los shards SLIP-39 en /decrypt, hacer preguntas al soporte — sin que les quitemos el acceso en medio de su duelo.<br/><br/><strong>Heredabilidad:</strong> el asiento de por vida pasa a tu beneficiario principal al activarse. Obtienen un año gratis de nuestra parte como el nuevo titular de la cuenta, y luego convierten al nivel que les convenga. Creemos que esto es lo más honesto que un producto de herencia cripto puede hacer — asegurarse de que la persona que realmente hereda tenga una cuenta funcional, no un paywall.<br/><br/><strong>Por qué lo construimos:</strong> las suscripciones recurrentes son el modo de fallo silencioso #1 en el estate planning. La gente configura un testamento, un Legacy Plan, un formulario de beneficiario — y luego una tarjeta caduca, un banco cierra, un correo va a spam, y todo deja de funcionar en silencio. Pagar una vez elimina ese modo de fallo por completo. También es significativamente más barato que lo que la mayoría de los abogados de estate planning cobran por una sola revisión de testamento.<br/><br/><strong>Paga con tarjeta o cripto:</strong> $499 vía Stripe, o ~$449 en cualquiera de 25 criptomonedas soportadas (BTC, ETH, XRP, SOL, RLUSD, XLM y más) con un descuento on-chain automático del 10%." },
    "Can the Legacy Plan pre-fill from my connected wallets?": { q: "¿Puede el Legacy Plan rellenarse previamente desde mis wallets conectados?", a: "Sí. Cuando añades un beneficiario y seleccionas un tipo de wallet, el sistema revisa tus wallets conectados y te muestra cuáles podrían estar en ese dispositivo. Selecciona los wallets que están en ese hardware, haz clic en 'Load Selected,' y el resumen de activos se rellena automáticamente con direcciones de wallet reales y saldos actuales — para que tu sobreviviente vea exactamente qué activos hay en cada dispositivo. Puedes editar el resumen antes de guardar. Esto significa que no tienes que recordar qué hay en cada dispositivo — los datos vienen directamente de tu portafolio." },
    "When I connect MetaMask, is my seed phrase or private key shared with CryptoOwnBank?": { q: "Cuando conecto MetaMask, ¿se comparte mi seed phrase o clave privada con CryptoOwnBank?", a: "Absolutamente no. Cuando haces clic en 'Connect Wallet' en CryptoOwnBank, la extensión del navegador MetaMask abre su propio popup — esta es la interfaz de MetaMask, no la nuestra. Si estás conectando MetaMask por primera vez, MetaMask puede pedirte que crees un nuevo wallet o importes uno existente usando tu frase de recuperación. Todo ese proceso ocurre dentro de la extensión MetaMask en tu dispositivo. Tu seed phrase se introduce en la interfaz segura propia de MetaMask, se cifra y se almacena localmente en tu computadora — nunca se envía a CryptoOwnBank, nunca se transmite a nuestros servidores, y no tenemos forma de verla. Después de configurar MetaMask, simplemente apruebas una solicitud de conexión — MetaMask comparte solo tu dirección pública de wallet con nuestro sitio, que es la misma dirección que cualquiera puede consultar en un explorador de blockchain. Usamos esa dirección para mostrar tus saldos, preparar transacciones sin firmar y mostrar cotizaciones de swap. Cuando ejecutas un swap o apruebas un token, MetaMask vuelve a aparecer pidiendo confirmación — y solo entonces MetaMask firma la transacción con tu clave privada localmente en tu dispositivo. La transacción firmada va directamente a la blockchain. En ningún momento CryptoOwnBank tiene acceso a tus claves privadas, seed phrase o autoridad de firma. Este es el mismo modelo de seguridad que usa toda app DeFi legítima — Uniswap, Aave, OpenSea — todas funcionan a través de la extensión MetaMask de la misma manera." },
    "Why does CryptoOwnBank warn me when I paste a seed phrase anywhere on the site?": { q: "¿Por qué CryptoOwnBank me advierte cuando pego una seed phrase en cualquier parte del sitio?", a: "Porque ningún flujo legítimo de CryptoOwnBank necesita nunca que teclees tu seed phrase en nuestro sitio. Punto. Los únicos lugares donde una seed real debería aparecer son: en la pantalla de recuperación de tu hardware wallet, en tu placa de acero, y (brevemente, solo en tu navegador) en el divisor SLIP-39 y el combinador /decrypt — ambos de los cuales se ejecutan enteramente del lado del cliente y nunca transmiten. <br/><br/>Si pegas 12 o 24 palabras en una barra de búsqueda, un campo de dirección, un chat o cualquier otra entrada en nuestro sitio, una advertencia en la página se activa inmediatamente diciéndote que pares. Esto atrapa las formas más comunes en que la gente es drenada — páginas de phishing que se parecen a las nuestras, accidentes de copiar-pegar, o seguir malos consejos de 'agentes de soporte' estafadores. Preferimos molestarte con una advertencia a ver cómo lo pierdes todo por un momento de confusión." },
    "Is DCA non-custodial? Who holds my funds?": { q: "¿El DCA es no custodial? ¿Quién custodia mis fondos?", a: "100% no custodial. CryptoOwnBank nunca retiene, toca ni tiene acceso a tus fondos. El programador DCA se ejecuta del lado del servidor y crea una oferta DEX pendiente cuando toca tu compra — pero la oferta NO se envía a la blockchain hasta que tú personalmente la apruebas en tu wallet Xaman o LOBSTR. Tus claves privadas nunca salen de tu dispositivo. Si no apruebas una ejecución pendiente, no ocurre nada — tus fondos permanecen exactamente donde están." },
    "What do I get with Premium?": { q: "¿Qué obtengo con Premium?", a: "Premium desbloquea el cockpit completo — sé dueño de tu cripto, gestionala desde una sola interfaz, quédate con todos tus ingresos. Trading en XRPL DEX (44 pares con Quick Swap y libro de órdenes Advanced), trading en Stellar DEX (13 pares), conexiones ilimitadas a exchanges, direcciones de blockchain ilimitadas en las más de 32 cadenas, historial completo de transacciones, importación CSV, alertas de precio ilimitadas, Recommendations Hub completo con optimización de rendimiento personalizada que muestra oportunidades que de otro modo te perderías, Statement Insights que comparan las tasas de tu banco con los rendimientos on-chain, Whale Alerts extendidas con umbrales personalizados, Technical Analysis con todos los indicadores y hasta 10 años de datos de gráficos, y Crypto News personalizado que muestra artículos que coinciden con los activos que tienes. Elige mensual ($29/mo) o anual ($199/yr) para desbloquear también informes fiscales completos. Tu nivel de seguridad es tu elección — cold wallet, hot wallet, firma con hardware o teléfono." },
    "Why should I upgrade to Premium?": { q: "¿Por qué debería actualizar a Premium?", a: "Si tu cripto está repartida entre múltiples exchanges, wallets y protocolos DeFi, Premium te da un solo cockpit para verlo todo. En lugar de iniciar sesión en Binance, Coinbase, Ledger Live y Yahoo Finance por separado, ves tu portafolio completo en más de 32 blockchains, recomendaciones de rendimiento personalizadas con claridad on-chain vs custodial, responsabilidad fiscal e ingresos por rendimiento en un solo panel. El Recommendations Hub te muestra exactamente cuánto rendimiento te estás perdiendo y qué oportunidades on-chain coinciden con los activos que ya tienes." },
    "Can I pay for Premium with crypto?": { q: "¿Puedo pagar Premium con cripto?", a: "Sí — y ahorras 10% cuando lo haces. Aceptamos cripto en 25 blockchains: XRP, RLUSD, BTC, ETH, SOL, XLM, DOGE, LTC, ADA, AVAX, ALGO, ATOM, TRX, HBAR, DOT, VET, TON, MATIC, CRO, XDC, DGB, CSPR, CKB, ZIL y XVG. Premium baja a $26.10/mo o $179.10/yr, y Pro baja a $89.10/mo o $719.10/yr — todo 10% menos que los precios con tarjeta. Ve a Settings → Subscription → Pay with Crypto, selecciona tu cadena, y te mostramos el monto exacto (preciado en vivo vía CoinGecko) y la dirección de wallet a la que enviar. Para XRP y RLUSD, también obtienes un destination tag único para emparejar tu pago. Nuestro sistema verifica tu pago on-chain y activa tu suscripción de inmediato. Sin KYC, sin cuenta bancaria, sin tarjeta de crédito — solo envía cripto y estás actualizado. Los pagos con tarjeta vía Stripe están disponibles como alternativa." },
    "Can I cancel Premium anytime?": { q: "¿Puedo cancelar Premium en cualquier momento?", a: "Sí. Puedes cancelar tu suscripción en cualquier momento. Conservarás el acceso Premium hasta el final de tu período de facturación actual. Sin penalizaciones, sin preguntas." },
    "What happens if I cancel my subscription or leave CryptoOwnBank?": { q: "¿Qué pasa si cancelo mi suscripción o dejo CryptoOwnBank?", a: "Nada le ocurre a tu cripto. Ese es todo el punto. Porque CryptoOwnBank es no custodial, nunca retenemos tus activos. Si cancelas Premium, bajas a Free o te vas por completo — tu cripto sigue en tu wallet, tu posición de Soil vault sigue generando rendimiento, tus trustlines siguen activas, y puedes acceder a todo a través de Xaman, tu Ledger o cualquier otra herramienta compatible con XRPL. Estás pagando por el panel, las analíticas, el Recommendations Hub y las herramientas de trading — no por la custodia de tus activos. Puedes dejarnos y seguir teniendo el control total. (Pero esperamos que no quieras.)" },
    "Why do BTC, ETH, SOL, XRP, and RLUSD get a bigger discount?": { q: "¿Por qué BTC, ETH, SOL, XRP y RLUSD obtienen un descuento mayor?", a: "Llamamos a esos cinco nuestro <strong>House Tier</strong> — paga tu suscripción, complemento o Legacy Lifetime en cualquiera de ellos y obtienes el mismo <strong>descuento on-chain plano del 10%</strong> que toda criptomoneda soportada. House Tier es una designación de moneda preferida, no un descuento extra. La razón es una alineación honesta de tesorería: BTC, ETH y SOL son activos blue-chip con los que nos sentimos cómodos manteniendo (tienden a apreciarse con el tiempo, denominados en dólares que no lo hacen), y XRP/RLUSD son nuestra cadena de origen — RLUSD literalmente financia los vaults de Soil Protocol que pagan a nuestros miembros 5–8% APR. Cuando nos pagas en esos activos, estás contribuyendo efectivamente a una tesorería que queremos hacer crecer en lugar de a un payout de Stripe que tenemos que convertir. Te devolvemos el ahorro como el descuento mayor.<br/><br/>Las otras 20 criptomonedas soportadas (DOGE, LTC, ADA, AVAX, ATOM, XLM, TON, MATIC y más) siguen obteniendo el descuento on-chain estándar del 10% frente al pago con tarjeta — son absolutamente bienvenidas, solo que no forman parte del house tier.<br/><br/><strong>Founder Badge:</strong> si compras <strong>Legacy Plan Lifetime</strong> en cualquier moneda House Tier, tu cuenta obtiene una insignia permanente y visible de Founding Member mostrando en qué moneda pagaste y el mes. Es nuestra forma de dar las gracias a los miembros que pusieron Bitcoin, Ether, Solana o XRP real en la plataforma desde el día uno." },
    "How safe is my principal?": { q: "¿Qué tan seguro está mi principal?", a: "Tu principal está protegido de dos maneras: 1) Diseño no custodial — las claves nunca salen de tu cold wallet. 2) Los Soil vaults están respaldados por activos del mundo real (Treasuries, fondos de crédito) con underwriting de grado institucional. Soil publica APR objetivo fijos, pero los rendimientos no están garantizados — cripto/blockchain siempre conlleva riesgos (bugs de smart contracts, cambios de protocolo, eventos de mercado, riesgo de contraparte/RWA). Siempre haz DYOR." },
    "Can I use Soil vaults without Premium?": { q: "¿Puedo usar Soil vaults sin Premium?", a: "Sí. Conectar tu wallet XRPL, depositar en <a href=\"/ownbank/vaults\" class=\"text-[#00A4E4] underline hover:no-underline\">Soil vaults</a>, y <a href=\"/ownbank/withdraw\" class=\"text-[#00A4E4] underline hover:no-underline\">retirar vía Soil</a> son todo gratis. Premium añade DCA para la conversión automática de RLUSD a XRP." },
  },
  pt: {
    "What is CryptoOwnBank?": { q: "O que é o CryptoOwnBank?", a: "CryptoOwnBank é onde tudo começa — e não termina. Seja dono da sua cripto, gerencie-a a partir de uma única interface e fique com todos os seus ganhos. Todo o trabalho é feito por você: o Recommendations Hub mostra rendimentos que você perderia, o Statement Insights compara as taxas do seu banco com as on-chain, os relatórios fiscais são gerados automaticamente e a informação chega até você. Acompanhe seu portfólio em mais de 32 blockchains, ganhe 5–8% de rendimento fixo em RLUSD, negocie em DEXs nativos, envie pagamentos globalmente — suas chaves ficam nas suas mãos. Escolha sua segurança: cold wallet, hot wallet, assinatura com hardware ou telefone. Se você sair algum dia, sua cripto continua na sua wallet. E o Legacy Plan garante que sua cripto passe para sua família se algo acontecer com você — então realmente não termina. Quer você seja unbanked, debanked ou simplesmente esteja cansado de confiar em plataformas que podem falhar — CryptoOwnBank dá as ferramentas para ser seu próprio banco." },
    "Why was CryptoOwnBank created? (And why should I use it?)": { q: "Por que o CryptoOwnBank foi criado? (E por que eu deveria usá-lo?)", a: "CryptoOwnBank foi criado porque exchanges podem falhar, congelar ou ir à falência — e quando isso acontece, seus fundos ficam presos. FTX. Celsius. Voyager. Mt. Gox. Pessoas confiaram plataformas com bilhões, e essas plataformas falharam. CryptoOwnBank existe para que sua cripto nunca esteja nas mãos de mais ninguém. Construímos para resolver cinco problemas: (1) Propriedade plena — sua wallet permanece sob seu controle. Nunca vemos nem armazenamos suas chaves privadas. Mesmo se você sair do CryptoOwnBank, sua cripto permanece na sua wallet. Você nunca fica preso. (2) Rendimentos reais que você fica — ganhe 5–8% APR fixo em RLUSD através do Soil Protocol, fique com cada centavo. Sem taxas de plataforma, sem intermediário. (3) Segurança nos seus termos — cold wallet, hot wallet, assinatura com hardware ou telefone. Você escolhe. Nenhum terceiro desinteressado no seu processo de decisão. (4) Todo o trabalho é feito por você — o Recommendations Hub mostra rendimentos que você perderia, o Statement Insights compara as taxas do seu banco com as on-chain, e a informação chega até você em vez de você ter que procurar. (5) Pense em valor, não em preço em USD — o dólar perde poder de compra todo ano, mas um XRP é um XRP não importa em cujas mãos esteja. Ajudamos você a ver o que sua cripto pode fazer, não só o que 'vale' em uma moeda que encolhe. É aqui que tudo começa. E não termina — o Legacy Plan (interruptor de homem morto) garante que sua cripto passe para sua família se algo acontecer com você. Não para uma exchange. Não para um tribunal de falências. Para as pessoas que você escolheu." },
    "Is this a wallet? Do you hold my funds?": { q: "Isto é uma wallet? Vocês custodian meus fundos?", a: "Não — somos 100% não custodiais. Nunca retemos, controlamos ou temos acesso aos seus fundos ou chaves privadas. Todas as ações de vault (depósitos, saques) são assinadas diretamente da sua própria wallet — cold ou hot, sua escolha. Para acompanhamento de portfólio, só lemos dados públicos on-chain. Aqui está a chave: mesmo se o CryptoOwnBank desaparecesse amanhã, sua cripto estaria exatamente onde está agora — na sua wallet. Você pode sair a qualquer momento e ainda ter controle e acesso total a tudo. Somos uma ferramenta que trabalha para você, não uma plataforma que custodia seus ativos." },
    "Is this safe? Do you hold my funds?": { q: "Isto é seguro? Vocês custodian meus fundos?", a: "Não — CryptoOwnBank é 100% não custodial. Nunca retemos, controlamos ou temos acesso aos seus fundos ou chaves privadas. Cada transação (mudanças de trustline, ordens DEX, pagamentos) é construída no seu navegador e assinada na sua cold wallet (Ledger ou Xumm/Xaman). Só lemos seu endereço público para exibir saldos e preparar transações não assinadas para você aprovar. Há zero risco de plataforma — mesmo se o CryptoOwnBank desaparecesse amanhã, seus fundos permanecem seguros na sua wallet na blockchain XRPL." },
    "Do you ever have access to my crypto? What if CryptoOwnBank shuts down?": { q: "Vocês alguma vez têm acesso à minha cripto? E se o CryptoOwnBank fechar?", a: "Não — em nenhum momento temos acesso à sua cripto. Somos 100% não custodiais. Nunca vemos suas chaves privadas, nunca retemos seus fundos e nunca temos a capacidade de mover seus ativos. Cada depósito em vault, saque, negociação e pagamento é assinado por você no seu próprio dispositivo. Esta é a diferença fundamental entre CryptoOwnBank e serviços custodiais: se uma empresa de custódia fechar, você está numa fila de credores esperando recuperar seus ativos (pergunte a qualquer cliente da FTX). Se o CryptoOwnBank fechasse amanhã, sua cripto ficaria completamente intacta. Seus fundos vivem na blockchain na sua wallet, não nos nossos servidores. Você poderia continuar usando sua cold wallet com qualquer outro app compatível com XRPL, acessar suas posições de Soil vault diretamente pelo Soil Protocol e ver seus saldos em qualquer explorador de blockchain. Somos uma camada de ferramentas sobre sua autocustódia — não um custodiante." },
    "Does CryptoOwnBank control my money or make decisions for me?": { q: "O CryptoOwnBank controla meu dinheiro ou toma decisões por mim?", a: "Não. Somos construídos em torno de uma ideia simples: nós trazemos tudo para a mesa, e você é o único que diz sim. Eis o que isso significa na prática — (1) Somos a mesa: tudo o que você precisa para configurar, revisar e agir está reunido num só lugar. (2) Somos o explicador: dizemos em palavras claras o que cada passo faz antes de você fazê-lo. (3) Somos a checklist e o rastreador: garantimos que nada que precise ser feito seja esquecido, e você pode acompanhar depois. (4) Você é o único que diz sim: nada acontece até você aprovar com sua própria wallet. Nunca retemos seu dinheiro, suas chaves ou sua frase de recuperação, e nunca decidimos com quem você pode negociar. Não estamos tentando nos conectar a todos e a tudo — o poder permanece com você e com a tecnologia, não conosco. Essa é a diferença entre uma ferramenta que trabalha para você e uma empresa que trabalha sobre você." },
    "Is CryptoOwnBank a bank, broker, or trust company?": { q: "O CryptoOwnBank é um banco, corretora ou trust company?", a: "Não. CryptoOwnBank é software não custodial — um painel e uma camada de ferramentas para wallets de autocustódia e protocolos on-chain. Não somos um banco, broker-dealer, transmisor de dinheiro nem trust company. Não retemos seus ativos, não garantimos retornos de investimento nem atuamos como fiduciário ou advogado de sucessões. As cifras de rendimento que você vê (por exemplo, APRs de Soil vault) vêm de protocolos de terceiros e não são garantidas pelo CryptoOwnBank. O Legacy Plan armazena instruções de recuperação criptografadas que você escreve — não é um testamento legal, instrumento de trust nem serviço custodial de herança." },
    "What is the Legacy Plan (dead-man switch)?": { q: "O que é o Legacy Plan (interruptor de homem morto)?", a: "O Legacy Plan protege sua cripto depois que você falecer — ou se ficar incapacitado. Está disponível como add-on avulso por <strong>$29/yr</strong> em qualquer plano, ou <strong>incluído grátis com Pro</strong> ($99/mo). É um interruptor de homem morto: você faz check-in num cronograma que escolhe (semanal, quinzenal, mensal ou trimestral). Se perder um check-in, começa um período de carência. Durante o período de carência, seu contato secundário (cônjuge, advogado etc.) é notificado para verificar seu status. Se o período de carência expirar sem resposta, seus beneficiários recebem as instruções de recuperação da wallet que você configurou — onde seu hardware wallet está guardado, onde o backup da seed phrase está localizado, como acessar um setup CypheRock 2-of-5 Shamir etc.<br/><br/><strong>O que NUNCA armazenamos:</strong> seed phrases, chaves privadas, senhas ou PINs. Só armazenamos SUAS instruções sobre <em>onde</em> essas coisas estão — 'placa de aço no cofre à prova de fogo' ou 'Cartão 1 com o advogado, Cartão 3 no cofre do banco.' Tudo é criptografado em repouso e entregue só quando o interruptor dispara. Member for Life — sua cripto não morre com você." },
    "How does the Legacy Plan check-in work?": { q: "Como funciona o check-in do Legacy Plan?", a: "Você pressiona o botão 'I'm Still Here' no painel do seu Legacy Plan. É só isso — um clique reinicia seu temporizador. Você escolhe a frequência: semanal, quinzenal, mensal (recomendado) ou trimestral. Se perder um check-in, o sistema entra num período de carência (padrão 14 dias, configurável até 90 dias). Durante a carência, seu contato secundário é notificado para tentar alcançá-lo. Se você ainda não fizer check-in até o fim do período de carência, o sistema dispara e seus beneficiários recebem suas instruções. Você pode fazer check-in a qualquer momento — mesmo durante o período de carência — para resetar tudo ao normal." },
    "Is the Legacy Plan really 'Member for Life'?": { q: "O Legacy Plan é realmente 'Member for Life'?", a: "Sim — e você tem três formas de pagar: <strong>$29/yr</strong>, <strong>$99/5yr</strong>, ou <strong>$499 once for life</strong>. O plano Pro ($99/mo ou $799/yr) inclui Legacy Plan grátis. Qualquer opção que escolher, o temporizador de check-in continua rodando, suas instruções de beneficiários ficam criptografadas e prontas, e o interruptor de homem morto está sempre armado. Se uma assinatura mensal ou anual caducar, o plano é pausado (não excluído) — seus dados são preservados para que você possa retomar a qualquer momento. A opção vitalícia é a que a maioria dos membros acaba escolhendo quando percebe que o ponto do planejamento sucessório é que ele deve sobreviver ao vencimento de um cartão, ao fechamento de um banco ou a uma renovação esquecida." },
    "What is Split Delivery for the Legacy Plan?": { q: "O que é Split Delivery para o Legacy Plan?", a: "Split delivery é como multi-sig para e-mail — em vez de um beneficiário receber todas as instruções de recuperação da wallet, você divide a informação entre várias pessoas para que elas precisem colaborar. Por exemplo, a Pessoa A recebe 'o Ledger está no cofre do home office' e a Pessoa B recebe 'a placa de aço da seed phrase está no cofre do banco #42.' Nenhuma pessoa sozinha pode acessar a wallet.<br/><br/>Você pode escolher <strong>All Required</strong> (a peça de cada beneficiário é necessária) ou <strong>Threshold</strong> (M-of-N, como Shamir — p.ex. quaisquer 2-of-3 beneficiários podem reconstruir as instruções completas). Isso combina perfeitamente com o sistema de cartões 2-of-5 do CypheRock — dê locais de cartão diferentes a beneficiários diferentes. Nenhum concorrente oferece divisão no nível de entrega assim. Ative com um toggle no painel do seu Legacy Plan." },
    "What is the Legacy Plan Lifetime ($499 one-time)?": { q: "O que é o Legacy Plan Lifetime ($499 one-time)?", a: "Legacy Plan Lifetime é um pagamento único de $499 (ou ~$449 em cripto com nosso desconto on-chain de 10%) que lhe dá o Legacy Plan para sempre — sem cobranças recorrentes, sem falhas de cartão expirado, sem risco de que uma assinatura esquecida faça o plano caducar exatamente quando mais se precisa. O Lifetime cobre você enquanto estiver vivo E por 12 meses após o disparo do seu interruptor de homem morto e a liberação das instruções de recuperação aos seus beneficiários. Esse ano extra existe para que seus sobreviventes tenham tempo de realmente usar o sistema — ler os e-mails, combinar os shards SLIP-39 em /decrypt, fazer perguntas ao suporte — sem que tiremos o acesso no meio do luto.<br/><br/><strong>Herdabilidade:</strong> o assento vitalício passa ao seu beneficiário principal no disparo. Eles ganham um ano grátis de nossa parte como o novo titular da conta, e depois convertem para o plano que lhes convier. Achamos que isso é a coisa mais honesta que um produto de herança cripto pode fazer — garantir que a pessoa que realmente herda tenha uma conta funcional, não um paywall.<br/><br/><strong>Por que construímos:</strong> assinaturas recorrentes são o modo de falha silenciosa #1 no planejamento sucessório. As pessoas configuram um testamento, um Legacy Plan, um formulário de beneficiário — e depois um cartão expira, um banco fecha, um e-mail vai para spam, e tudo para de funcionar em silêncio. Pagar uma vez remove esse modo de falha por completo. Também é significativamente mais barato do que o que a maioria dos advogados de planejamento sucessório cobra por uma única revisão de testamento.<br/><br/><strong>Pague com cartão ou cripto:</strong> $499 via Stripe, ou ~$449 em qualquer uma de 25 criptomoedas suportadas (BTC, ETH, XRP, SOL, RLUSD, XLM e mais) com desconto on-chain automático de 10%." },
    "Can the Legacy Plan pre-fill from my connected wallets?": { q: "O Legacy Plan pode pré-preencher a partir das minhas wallets conectadas?", a: "Sim. Quando você adiciona um beneficiário e seleciona um tipo de wallet, o sistema verifica suas wallets conectadas e mostra quais podem estar naquele dispositivo. Selecione as wallets que estão naquele hardware, clique em 'Load Selected,' e o resumo de ativos é preenchido automaticamente com endereços reais de wallet e saldos atuais — para que seu sobrevivente veja exatamente quais ativos estão em cada dispositivo. Você pode editar o resumo antes de salvar. Isso significa que você não precisa lembrar o que há em cada dispositivo — os dados vêm direto do seu portfólio." },
    "When I connect MetaMask, is my seed phrase or private key shared with CryptoOwnBank?": { q: "Quando conecto o MetaMask, minha seed phrase ou chave privada é compartilhada com o CryptoOwnBank?", a: "Absolutamente não. Quando você clica em 'Connect Wallet' no CryptoOwnBank, a extensão do navegador MetaMask abre seu próprio popup — esta é a interface do MetaMask, não a nossa. Se estiver conectando o MetaMask pela primeira vez, o MetaMask pode pedir que você crie uma nova wallet ou importe uma existente usando sua frase de recuperação. Todo esse processo acontece dentro da extensão MetaMask no seu dispositivo. Sua seed phrase é inserida na interface segura própria do MetaMask, criptografada e armazenada localmente no seu computador — nunca é enviada ao CryptoOwnBank, nunca transmitida aos nossos servidores, e não temos como vê-la. Depois que o MetaMask está configurado, você simplesmente aprova um pedido de conexão — o MetaMask compartilha apenas seu endereço público de wallet com nosso site, que é o mesmo endereço que qualquer um pode consultar num explorador de blockchain. Usamos esse endereço para exibir seus saldos, preparar transações não assinadas e mostrar cotações de swap. Quando você executa um swap ou aprova um token, o MetaMask aparece de novo pedindo confirmação — e só então o MetaMask assina a transação com sua chave privada localmente no seu dispositivo. A transação assinada vai direto para a blockchain. Em nenhum momento o CryptoOwnBank tem acesso às suas chaves privadas, seed phrase ou autoridade de assinatura. Este é o mesmo modelo de segurança usado por todo app DeFi legítimo — Uniswap, Aave, OpenSea — todos funcionam pela extensão MetaMask da mesma forma." },
    "Why does CryptoOwnBank warn me when I paste a seed phrase anywhere on the site?": { q: "Por que o CryptoOwnBank me avisa quando colo uma seed phrase em qualquer lugar do site?", a: "Porque nenhum fluxo legítimo do CryptoOwnBank precisa jamais que você digite sua seed phrase no nosso site. Ponto final. Os únicos lugares onde uma seed real deveria aparecer são: na tela de recuperação do seu hardware wallet, na sua placa de aço, e (brevemente, só no seu navegador) no divisor SLIP-39 e no combinador /decrypt — ambos dos quais rodam inteiramente no lado do cliente e nunca transmitem. <br/><br/>Se você colar 12 ou 24 palavras numa barra de busca, num campo de endereço, numa caixa de chat ou em qualquer outra entrada no nosso site, um aviso na página dispara imediatamente dizendo para parar. Isso captura as formas mais comuns de as pessoas serem drenadas — páginas de phishing que parecem com as nossas, acidentes de copiar-colar, ou seguir maus conselhos de 'agentes de suporte' golpistas. Preferimos incomodá-lo com um aviso a ver você perder tudo por um momento de confusão." },
    "Is DCA non-custodial? Who holds my funds?": { q: "O DCA é não custodial? Quem custodia meus fundos?", a: "100% não custodial. CryptoOwnBank nunca retém, toca ou tem acesso aos seus fundos. O agendador DCA roda no lado do servidor e cria uma oferta DEX pendente quando sua compra vence — mas a oferta NÃO é enviada à blockchain até que você pessoalmente a aprove na sua wallet Xaman ou LOBSTR. Suas chaves privadas nunca saem do seu dispositivo. Se você não aprovar uma execução pendente, nada acontece — seus fundos ficam exatamente onde estão." },
    "What do I get with Premium?": { q: "O que eu ganho com o Premium?", a: "Premium destrava o cockpit completo — seja dono da sua cripto, gerencie-a a partir de uma única interface, fique com todos os seus ganhos. Trading no XRPL DEX (44 pares com Quick Swap e livro de ordens Advanced), trading no Stellar DEX (13 pares), conexões ilimitadas a exchanges, endereços de blockchain ilimitados em todas as 32+ chains, histórico completo de transações, importação CSV, alertas de preço ilimitados, Recommendations Hub completo com otimização de rendimento personalizada que mostra oportunidades que você perderia de outra forma, Statement Insights que comparam as taxas do seu banco com rendimentos on-chain, Whale Alerts estendidos com limiares personalizados, Technical Analysis com todos os indicadores e até 10 anos de dados de gráfico, e Crypto News personalizado que mostra artigos que correspondem aos ativos que você possui. Escolha mensal ($29/mo) ou anual ($199/yr) para também desbloquear relatórios fiscais completos. Seu nível de segurança é sua escolha — cold wallet, hot wallet, assinatura com hardware ou telefone." },
    "Why should I upgrade to Premium?": { q: "Por que eu deveria fazer upgrade para Premium?", a: "Se sua cripto está espalhada por múltiplas exchanges, wallets e protocolos DeFi, Premium dá a você um único cockpit para ver tudo. Em vez de entrar no Binance, Coinbase, Ledger Live e Yahoo Finance separadamente, você vê seu portfólio inteiro em mais de 32 blockchains, recomendações de rendimento personalizadas com clareza on-chain vs custodial, responsabilidade fiscal e ganhos de rendimento num único painel. O Recommendations Hub mostra exatamente quanto rendimento você está perdendo e quais oportunidades on-chain combinam com os ativos que você já possui." },
    "Can I pay for Premium with crypto?": { q: "Posso pagar o Premium com cripto?", a: "Sim — e você economiza 10% quando faz isso. Aceitamos cripto em 25 blockchains: XRP, RLUSD, BTC, ETH, SOL, XLM, DOGE, LTC, ADA, AVAX, ALGO, ATOM, TRX, HBAR, DOT, VET, TON, MATIC, CRO, XDC, DGB, CSPR, CKB, ZIL e XVG. Premium cai para $26.10/mo ou $179.10/yr, e Pro cai para $89.10/mo ou $719.10/yr — tudo 10% abaixo dos preços com cartão. Vá em Settings → Subscription → Pay with Crypto, selecione sua chain, e mostramos o valor exato (preço ao vivo via CoinGecko) e o endereço da wallet para enviar. Para XRP e RLUSD, você também recebe um destination tag único para combinar seu pagamento. Nosso sistema verifica seu pagamento on-chain e ativa sua assinatura imediatamente. Sem KYC, sem conta bancária, sem cartão de crédito — só envie cripto e você está no upgrade. Pagamentos com cartão via Stripe estão disponíveis como fallback." },
    "Can I cancel Premium anytime?": { q: "Posso cancelar o Premium a qualquer momento?", a: "Sim. Você pode cancelar sua assinatura a qualquer momento. Manterá o acesso Premium até o fim do seu período de cobrança atual. Sem penalidades, sem perguntas." },
    "What happens if I cancel my subscription or leave CryptoOwnBank?": { q: "O que acontece se eu cancelar minha assinatura ou sair do CryptoOwnBank?", a: "Nada acontece com sua cripto. Esse é todo o ponto. Porque o CryptoOwnBank é não custodial, nunca retemos seus ativos. Se você cancelar o Premium, fizer downgrade para Free ou sair por completo — sua cripto continua na sua wallet, sua posição de Soil vault continua gerando rendimento, suas trustlines continuam ativas, e você pode acessar tudo pelo Xaman, seu Ledger ou qualquer outra ferramenta compatível com XRPL. Você está pagando pelo painel, pelas análises, pelo Recommendations Hub e pelas ferramentas de trading — não pela custódia dos seus ativos. Você pode nos deixar e ainda estar no controle total. (Mas esperamos que não queira.)" },
    "Why do BTC, ETH, SOL, XRP, and RLUSD get a bigger discount?": { q: "Por que BTC, ETH, SOL, XRP e RLUSD ganham um desconto maior?", a: "Chamamos esses cinco de nosso <strong>House Tier</strong> — pague sua assinatura, add-on ou Legacy Lifetime em qualquer um deles e você recebe o mesmo <strong>desconto on-chain plano de 10%</strong> de toda criptomoeda suportada. House Tier é uma designação de moeda preferida, não um desconto extra. A razão é alinhamento honesto de tesouraria: BTC, ETH e SOL são ativos blue-chip com os quais nos sentimos confortáveis em manter (tendem a se valorizar com o tempo, denominados em dólares que não), e XRP/RLUSD são nossa chain de origem — RLUSD literalmente financia os vaults do Soil Protocol que pagam aos nossos membros 5–8% APR. Quando você nos paga nesses ativos, está efetivamente contribuindo para uma tesouraria que queremos fazer crescer em vez de um payout do Stripe que temos que converter. Passamos a economia de volta para você como o desconto maior.<br/><br/>As outras 20 criptomoedas suportadas (DOGE, LTC, ADA, AVAX, ATOM, XLM, TON, MATIC e mais) ainda recebem o desconto on-chain padrão de 10% versus pagamento com cartão — são absolutamente bem-vindas, só não fazem parte do house tier.<br/><br/><strong>Founder Badge:</strong> se você comprar <strong>Legacy Plan Lifetime</strong> em qualquer moeda House Tier, sua conta ganha um badge permanente e visível de Founding Member mostrando em qual moeda você pagou e o mês. É nossa forma de agradecer aos membros que colocaram Bitcoin, Ether, Solana ou XRP reais na plataforma no dia um." },
    "How safe is my principal?": { q: "Quão seguro está meu principal?", a: "Seu principal está protegido de duas formas: 1) Design não custodial — as chaves nunca saem da sua cold wallet. 2) Os Soil vaults são lastreados por ativos do mundo real (Treasuries, fundos de crédito) com underwriting de grau institucional. Soil publica APRs-alvo fixos, mas os retornos não são garantidos — cripto/blockchain sempre carrega riscos (bugs de smart contract, mudanças de protocolo, eventos de mercado, risco de contraparte/RWA). Sempre faça DYOR." },
    "Can I use Soil vaults without Premium?": { q: "Posso usar Soil vaults sem Premium?", a: "Sim. Conectar sua wallet XRPL, depositar em <a href=\"/ownbank/vaults\" class=\"text-[#00A4E4] underline hover:no-underline\">Soil vaults</a>, e <a href=\"/ownbank/withdraw\" class=\"text-[#00A4E4] underline hover:no-underline\">sacar via Soil</a> são tudo grátis. Premium adiciona DCA para conversão automática de RLUSD para XRP." },
  },
  fr: {
    "What is CryptoOwnBank?": { q: "Qu'est-ce que CryptoOwnBank ?", a: "CryptoOwnBank, c'est là où tout commence — et ça ne s'arrête pas. Possédez votre crypto, gérez-la depuis une seule interface, gardez tous vos gains. Tout le travail est fait pour vous : le Recommendations Hub fait apparaître les rendements que vous manqueriez, Statement Insights compare les taux de votre banque aux rendements on-chain, les rapports fiscaux sont générés automatiquement, et l'information vient à vous. Suivez votre portefeuille sur plus de 32 blockchains, gagnez 5–8% de rendement fixe sur RLUSD, tradez sur des DEX natifs, envoyez des paiements dans le monde entier — vos clés restent entre vos mains. Choisissez votre sécurité : cold wallet, hot wallet, signature hardware ou téléphone. Si vous partez un jour, votre crypto est toujours dans votre wallet. Et le Legacy Plan veille à ce que votre crypto passe à votre famille si quelque chose vous arrive — donc ça ne s'arrête vraiment pas. Que vous soyez unbanked, debanked, ou simplement fatigué de faire confiance à des plateformes qui peuvent faillir — CryptoOwnBank vous donne les outils pour être votre propre banque." },
    "Why was CryptoOwnBank created? (And why should I use it?)": { q: "Pourquoi CryptoOwnBank a-t-il été créé ? (Et pourquoi devrais-je l'utiliser ?)", a: "CryptoOwnBank a été créé parce que les exchanges peuvent faillir, geler ou faire faillite — et quand c'est le cas, vos fonds sont piégés. FTX. Celsius. Voyager. Mt. Gox. Des gens ont confié des milliards à des plateformes, et ces plateformes ont failli. CryptoOwnBank existe pour que votre crypto ne soit jamais entre les mains de quelqu'un d'autre. Nous l'avons construit pour résoudre cinq problèmes : (1) Pleine propriété — votre wallet reste sous votre contrôle. Nous ne voyons ni ne stockons jamais vos clés privées. Même si vous quittez CryptoOwnBank, votre crypto reste dans votre wallet. Vous n'êtes jamais enfermé. (2) De vrais rendements que vous gardez — gagnez 5–8% d'APR fixe sur RLUSD via Soil Protocol, gardez chaque centime. Pas de frais de plateforme, pas d'intermédiaire. (3) Sécurité selon vos termes — cold wallet, hot wallet, signature hardware ou téléphone. Vous choisissez. Aucun tiers désintéressé dans votre processus de décision. (4) Tout le travail est fait pour vous — le Recommendations Hub fait apparaître les rendements que vous manqueriez, Statement Insights compare les taux de votre banque aux on-chain, et l'information vient à vous au lieu que vous alliez la chercher. (5) Pensez en valeur, pas en prix USD — le dollar perd du pouvoir d'achat chaque année, mais un XRP est un XRP peu importe entre quelles mains il se trouve. Nous vous aidons à voir ce que votre crypto peut faire, pas seulement ce qu'elle « vaut » dans une monnaie qui rétrécit. C'est là que tout commence. Et ça ne s'arrête pas — le Legacy Plan (interrupteur homme mort) veille à ce que votre crypto passe à votre famille si quelque chose vous arrive. Pas à un exchange. Pas à un tribunal de faillite. Aux personnes que vous avez choisies." },
    "Is this a wallet? Do you hold my funds?": { q: "Est-ce un wallet ? Détenez-vous mes fonds ?", a: "Non — nous sommes 100 % non-custodial. Nous ne détenons, ne contrôlons ni n'avons jamais accès à vos fonds ou clés privées. Toutes les actions de vault (dépôts, retraits) sont signées directement depuis votre propre wallet — cold ou hot, à vous de choisir. Pour le suivi de portefeuille, nous ne lisons que des données publiques on-chain. Voici le point clé : même si CryptoOwnBank disparaissait demain, votre crypto serait exactement là où elle est maintenant — dans votre wallet. Vous pouvez partir à tout moment et garder le contrôle et l'accès complets à tout. Nous sommes un outil qui travaille pour vous, pas une plateforme qui détient vos actifs." },
    "Is this safe? Do you hold my funds?": { q: "Est-ce sûr ? Détenez-vous mes fonds ?", a: "Non — CryptoOwnBank est 100 % non-custodial. Nous ne détenons, ne contrôlons ni n'avons jamais accès à vos fonds ou clés privées. Chaque transaction (modifications de trustline, ordres DEX, paiements) est construite dans votre navigateur et signée sur votre cold wallet (Ledger ou Xumm/Xaman). Nous ne lisons que votre adresse publique pour afficher les soldes et préparer des transactions non signées à votre approbation. Il y a zéro risque de plateforme — même si CryptoOwnBank disparaissait demain, vos fonds restent en sécurité dans votre wallet sur la blockchain XRPL." },
    "Do you ever have access to my crypto? What if CryptoOwnBank shuts down?": { q: "Avez-vous un jour accès à ma crypto ? Que se passe-t-il si CryptoOwnBank ferme ?", a: "Non — à aucun moment nous n'avons accès à votre crypto. Nous sommes 100 % non-custodial. Nous ne voyons jamais vos clés privées, ne détenons jamais vos fonds, et n'avons jamais la capacité de déplacer vos actifs. Chaque dépôt en vault, retrait, trade et paiement est signé par vous sur votre propre appareil. C'est la différence fondamentale entre CryptoOwnBank et les services custodial : si une société de custodie ferme, vous êtes dans une file de créanciers espérant récupérer vos actifs (demandez à n'importe quel client FTX). Si CryptoOwnBank fermait demain, votre crypto serait totalement intacte. Vos fonds vivent sur la blockchain dans votre wallet, pas sur nos serveurs. Vous pourriez continuer à utiliser votre cold wallet avec toute autre app compatible XRPL, accéder à vos positions Soil vault directement via Soil Protocol, et consulter vos soldes sur n'importe quel explorateur blockchain. Nous sommes une couche d'outils au-dessus de votre self-custody — pas un custodian." },
    "Does CryptoOwnBank control my money or make decisions for me?": { q: "CryptoOwnBank contrôle-t-il mon argent ou prend-il des décisions pour moi ?", a: "Non. Nous sommes construits autour d'une idée simple : nous apportons tout sur la table, et vous êtes le seul à dire oui. Voici ce que cela signifie en pratique — (1) Nous sommes la table : tout ce dont vous avez besoin pour configurer, examiner et agir est rassemblé en un seul endroit. (2) Nous sommes l'explicateur : nous vous disons en mots simples ce que chaque étape fait avant que vous la fassiez. (3) Nous sommes la checklist et le tracker : nous veillons à ce que rien qui doive être fait ne soit oublié, et vous pouvez suivre ensuite. (4) Vous êtes le seul à dire oui : rien ne se passe tant que vous ne l'approuvez pas avec votre propre wallet. Nous ne détenons jamais votre argent, vos clés ou votre phrase de récupération, et nous ne décidons jamais avec qui vous avez le droit de traiter. Nous n'essayons pas de nous connecter à tout le monde et à tout — le pouvoir reste avec vous et la technologie, pas avec nous. C'est la différence entre un outil qui travaille pour vous et une entreprise qui travaille sur vous." },
    "Is CryptoOwnBank a bank, broker, or trust company?": { q: "CryptoOwnBank est-il une banque, un courtier ou une trust company ?", a: "Non. CryptoOwnBank est un logiciel non-custodial — un tableau de bord et une couche d'outils pour les wallets en self-custody et les protocoles on-chain. Nous ne sommes pas une banque, un broker-dealer, un money transmitter ni une trust company. Nous ne détenons pas vos actifs, ne garantissons pas de rendements d'investissement, et n'agissons pas comme fiduciaire ou avocat successoral. Les chiffres de rendement que vous voyez (par exemple les APR des Soil vaults) proviennent de protocoles tiers et ne sont pas garantis par CryptoOwnBank. Le Legacy Plan stocke des instructions de récupération chiffrées que vous rédigez — ce n'est pas un testament légal, un instrument de trust, ni un service custodial d'héritage." },
    "What is the Legacy Plan (dead-man switch)?": { q: "Qu'est-ce que le Legacy Plan (interrupteur homme mort) ?", a: "Le Legacy Plan protège votre crypto après votre décès — ou si vous devenez incapable. Il est disponible en add-on autonome pour <strong>$29/yr</strong> sur tout niveau, ou <strong>inclus gratuitement avec Pro</strong> ($99/mo). C'est un interrupteur homme mort : vous faites un check-in selon un calendrier que vous choisissez (hebdomadaire, bihebdomadaire, mensuel ou trimestriel). Si vous manquez un check-in, une période de grâce commence. Pendant la période de grâce, votre contact secondaire (conjoint, avocat, etc.) est notifié pour vérifier votre statut. Si la période de grâce expire sans réponse, vos bénéficiaires reçoivent les instructions de récupération du wallet que vous avez configurées — où votre hardware wallet est stocké, où se trouve la sauvegarde de la seed phrase, comment accéder à un setup CypheRock 2-of-5 Shamir, etc.<br/><br/><strong>Ce que nous ne stockons JAMAIS :</strong> seed phrases, clés privées, mots de passe ou PINs. Nous stockons uniquement VOS instructions sur <em>où</em> se trouvent ces choses — 'plaque d'acier dans le coffre-fort ignifuge' ou 'Carte 1 chez l'avocat, Carte 3 dans le coffre de banque.' Tout est chiffré au repos et livré uniquement lorsque l'interrupteur se déclenche. Member for Life — votre crypto ne meurt pas avec vous." },
    "How does the Legacy Plan check-in work?": { q: "Comment fonctionne le check-in du Legacy Plan ?", a: "Vous appuyez sur le bouton 'I'm Still Here' sur le tableau de bord de votre Legacy Plan. C'est tout — un clic réinitialise votre minuteur. Vous choisissez la fréquence : hebdomadaire, bihebdomadaire, mensuel (recommandé) ou trimestriel. Si vous manquez un check-in, le système entre dans une période de grâce (14 jours par défaut, configurable jusqu'à 90 jours). Pendant la grâce, votre contact secondaire est notifié pour qu'il puisse essayer de vous joindre. Si vous ne faites toujours pas de check-in à la fin de la période de grâce, le système se déclenche et vos bénéficiaires reçoivent leurs instructions. Vous pouvez faire un check-in à tout moment — même pendant la période de grâce — pour tout remettre à la normale." },
    "Is the Legacy Plan really 'Member for Life'?": { q: "Le Legacy Plan est-il vraiment 'Member for Life' ?", a: "Oui — et vous avez trois façons de le payer : <strong>$29/yr</strong>, <strong>$99/5yr</strong>, ou <strong>$499 once for life</strong>. Le niveau Pro ($99/mo ou $799/yr) inclut le Legacy Plan gratuitement. Quelle que soit votre option, le minuteur de check-in continue de tourner, vos instructions de bénéficiaires restent chiffrées et prêtes, et l'interrupteur homme mort est toujours armé. Si un abonnement mensuel ou annuel expire, le plan est mis en pause (pas supprimé) — vos données sont préservées pour que vous puissiez reprendre à tout moment. L'option à vie est celle que la plupart des membres finissent par choisir une fois qu'ils réalisent que le but de la planification successorale est qu'elle survive à l'expiration d'une carte, à la fermeture d'une banque ou à un renouvellement oublié." },
    "What is Split Delivery for the Legacy Plan?": { q: "Qu'est-ce que le Split Delivery pour le Legacy Plan ?", a: "Le split delivery, c'est comme du multi-sig pour l'e-mail — au lieu qu'un seul bénéficiaire reçoive toutes vos instructions de récupération de wallet, vous répartissez l'information entre plusieurs personnes pour qu'elles doivent collaborer. Par exemple, la Personne A reçoit 'le Ledger est dans le coffre du bureau à domicile' et la Personne B reçoit 'la plaque d'acier de la seed phrase est dans le coffre de banque #42.' Aucune personne seule ne peut accéder au wallet.<br/><br/>Vous pouvez choisir <strong>All Required</strong> (la pièce de chaque bénéficiaire est nécessaire) ou <strong>Threshold</strong> (M-of-N, comme Shamir — p.ex. n'importe quels 2-of-3 bénéficiaires peuvent reconstruire les instructions complètes). Cela s'associe parfaitement au système de cartes 2-of-5 de CypheRock — donnez des emplacements de cartes différents à des bénéficiaires différents. Aucun concurrent n'offre un découpage au niveau de la livraison comme celui-ci. Activez-le avec un interrupteur sur le tableau de bord de votre Legacy Plan." },
    "What is the Legacy Plan Lifetime ($499 one-time)?": { q: "Qu'est-ce que le Legacy Plan Lifetime ($499 one-time) ?", a: "Legacy Plan Lifetime est un paiement unique de $499 (ou ~$449 en crypto avec notre remise on-chain de 10%) qui vous donne le Legacy Plan pour toujours — sans frais récurrents, sans échecs de carte expirée, sans risque qu'un abonnement oublié fasse expirer le plan exactement au moment où on en a le plus besoin. Le Lifetime vous couvre tant que vous êtes en vie ET pendant 12 mois après le déclenchement de votre interrupteur homme mort et la libération des instructions de récupération à vos bénéficiaires. Cette année supplémentaire existe pour que vos survivants aient le temps d'utiliser réellement le système — lire les e-mails, combiner les shards SLIP-39 sur /decrypt, poser des questions au support — sans que nous leur retirions l'accès au milieu de leur deuil.<br/><br/><strong>Héritabilité :</strong> le siège à vie passe à votre bénéficiaire principal au déclenchement. Ils obtiennent une année gratuite de notre part en tant que nouveau titulaire du compte, puis convertissent vers le niveau qui leur convient. Nous pensons que c'est la chose la plus honnête qu'un produit d'héritage crypto puisse faire — s'assurer que la personne qui hérite vraiment a un compte fonctionnel, pas un paywall.<br/><br/><strong>Pourquoi nous l'avons construit :</strong> les abonnements récurrents sont le mode de défaillance silencieuse n°1 de la planification successorale. Les gens mettent en place un testament, un Legacy Plan, un formulaire de bénéficiaire — puis une carte expire, une banque ferme, un e-mail part en spam, et tout s'arrête silencieusement de fonctionner. Payer une fois élimine entièrement ce mode de défaillance. C'est aussi nettement moins cher que ce que la plupart des avocats en planification successorale facturent pour une seule révision de testament.<br/><br/><strong>Payez par carte ou crypto :</strong> $499 via Stripe, ou ~$449 dans l'une des 25 cryptomonnaies prises en charge (BTC, ETH, XRP, SOL, RLUSD, XLM, et plus) pour une remise on-chain automatique de 10%." },
    "Can the Legacy Plan pre-fill from my connected wallets?": { q: "Le Legacy Plan peut-il se préremplir depuis mes wallets connectés ?", a: "Oui. Lorsque vous ajoutez un bénéficiaire et sélectionnez un type de wallet, le système vérifie vos wallets connectés et vous montre lesquels pourraient être sur cet appareil. Sélectionnez les wallets qui sont sur ce hardware, cliquez sur 'Load Selected,' et le résumé des actifs se remplit automatiquement avec les adresses de wallet réelles et les soldes actuels — pour que votre survivant voie exactement quels actifs sont sur chaque appareil. Vous pouvez modifier le résumé avant d'enregistrer. Cela signifie que vous n'avez pas à vous souvenir de ce qu'il y a sur chaque appareil — les données viennent directement de votre portefeuille." },
    "When I connect MetaMask, is my seed phrase or private key shared with CryptoOwnBank?": { q: "Quand je connecte MetaMask, ma seed phrase ou clé privée est-elle partagée avec CryptoOwnBank ?", a: "Absolument pas. Quand vous cliquez sur 'Connect Wallet' sur CryptoOwnBank, l'extension navigateur MetaMask ouvre son propre popup — c'est l'interface de MetaMask, pas la nôtre. Si vous connectez MetaMask pour la première fois, MetaMask peut vous demander de créer un nouveau wallet ou d'importer un existant avec votre phrase de récupération. Tout ce processus se déroule dans l'extension MetaMask sur votre appareil. Votre seed phrase est saisie dans l'interface sécurisée propre à MetaMask, chiffrée et stockée localement sur votre ordinateur — elle n'est jamais envoyée à CryptoOwnBank, jamais transmise à nos serveurs, et nous n'avons aucun moyen de la voir. Une fois MetaMask configuré, vous approuvez simplement une demande de connexion — MetaMask ne partage que votre adresse publique de wallet avec notre site, la même adresse que n'importe qui peut consulter sur un explorateur blockchain. Nous utilisons cette adresse pour afficher vos soldes, préparer des transactions non signées et montrer des devis de swap. Quand vous exécutez un swap ou approuvez un token, MetaMask réapparaît pour demander confirmation — et ce n'est qu'alors que MetaMask signe la transaction avec votre clé privée localement sur votre appareil. La transaction signée va directement à la blockchain. À aucun moment CryptoOwnBank n'a accès à vos clés privées, seed phrase ou autorité de signature. C'est le même modèle de sécurité utilisé par toute app DeFi légitime — Uniswap, Aave, OpenSea — elles fonctionnent toutes via l'extension MetaMask de la même façon." },
    "Why does CryptoOwnBank warn me when I paste a seed phrase anywhere on the site?": { q: "Pourquoi CryptoOwnBank m'avertit-il quand je colle une seed phrase n'importe où sur le site ?", a: "Parce qu'aucun flux légitime de CryptoOwnBank n'a jamais besoin que vous tapiez votre seed phrase sur notre site. Point final. Les seuls endroits où une vraie seed devrait apparaître sont : sur l'écran de récupération de votre hardware wallet, sur votre plaque d'acier, et (brièvement, dans votre navigateur uniquement) dans le diviseur SLIP-39 et le combineur /decrypt — qui tournent entièrement côté client et ne transmettent jamais. <br/><br/>Si vous collez 12 ou 24 mots dans une barre de recherche, un champ d'adresse, une boîte de chat ou toute autre entrée sur notre site, un avertissement in-page se déclenche immédiatement pour vous dire d'arrêter. Cela attrape les façons les plus courantes dont les gens se font drainer — pages de phishing qui ressemblent aux nôtres, accidents de copier-coller, ou suivi de mauvais conseils d'« agents de support » escrocs. Nous préférons vous agacer avec un avertissement plutôt que de vous voir tout perdre à cause d'un moment de confusion." },
    "Is DCA non-custodial? Who holds my funds?": { q: "Le DCA est-il non-custodial ? Qui détient mes fonds ?", a: "100 % non-custodial. CryptoOwnBank ne détient, ne touche ni n'a jamais accès à vos fonds. Le planificateur DCA tourne côté serveur et crée une offre DEX en attente quand votre achat est dû — mais l'offre N'EST PAS soumise à la blockchain tant que vous ne l'approuvez pas personnellement dans votre wallet Xaman ou LOBSTR. Vos clés privées ne quittent jamais votre appareil. Si vous n'approuvez pas une exécution en attente, rien ne se passe — vos fonds restent exactement où ils sont." },
    "What do I get with Premium?": { q: "Qu'est-ce que j'obtiens avec Premium ?", a: "Premium débloque le cockpit complet — possédez votre crypto, gérez-la depuis une seule interface, gardez tous vos gains. Trading XRPL DEX (44 paires avec Quick Swap et carnet d'ordres Advanced), trading Stellar DEX (13 paires), connexions d'exchange illimitées, adresses blockchain illimitées sur les 32+ chains, historique complet des transactions, import CSV, alertes de prix illimitées, Recommendations Hub complet avec optimisation de rendement personnalisée qui fait apparaître les opportunités que vous manqueriez autrement, Statement Insights qui comparent les taux de votre banque aux rendements on-chain, Whale Alerts étendus avec seuils personnalisés, Technical Analysis avec tous les indicateurs et jusqu'à 10 ans de données de graphiques, et Crypto News personnalisé qui fait apparaître des articles correspondant aux actifs que vous détenez. Choisissez mensuel ($29/mo) ou annuel ($199/yr) pour débloquer aussi les rapports fiscaux complets. Votre niveau de sécurité est votre choix — cold wallet, hot wallet, signature hardware ou téléphone." },
    "Why should I upgrade to Premium?": { q: "Pourquoi devrais-je passer à Premium ?", a: "Si votre crypto est répartie sur plusieurs exchanges, wallets et protocoles DeFi, Premium vous donne un seul cockpit pour tout voir. Au lieu de vous connecter séparément à Binance, Coinbase, Ledger Live et Yahoo Finance, vous voyez l'ensemble de votre portefeuille sur plus de 32 blockchains, des recommandations de rendement personnalisées avec clarté on-chain vs custodial, la responsabilité fiscale et les gains de rendement dans un seul tableau de bord. Le Recommendations Hub vous montre exactement combien de rendement vous manquez et quelles opportunités on-chain correspondent aux actifs que vous détenez déjà." },
    "Can I pay for Premium with crypto?": { q: "Puis-je payer Premium en crypto ?", a: "Oui — et vous économisez 10% quand vous le faites. Nous acceptons la crypto sur 25 blockchains : XRP, RLUSD, BTC, ETH, SOL, XLM, DOGE, LTC, ADA, AVAX, ALGO, ATOM, TRX, HBAR, DOT, VET, TON, MATIC, CRO, XDC, DGB, CSPR, CKB, ZIL et XVG. Premium passe à $26.10/mo ou $179.10/yr, et Pro à $89.10/mo ou $719.10/yr — le tout 10% de moins que les prix carte. Allez dans Settings → Subscription → Pay with Crypto, sélectionnez votre chain, et nous vous montrons le montant exact (tarifé en direct via CoinGecko) et l'adresse wallet à laquelle envoyer. Pour XRP et RLUSD, vous obtenez aussi un destination tag unique pour associer votre paiement. Notre système vérifie votre paiement on-chain et active votre abonnement immédiatement. Pas de KYC, pas de compte bancaire, pas de carte de crédit — envoyez juste de la crypto et vous êtes upgradé. Les paiements par carte via Stripe sont disponibles en secours." },
    "Can I cancel Premium anytime?": { q: "Puis-je annuler Premium à tout moment ?", a: "Oui. Vous pouvez annuler votre abonnement à tout moment. Vous conservez l'accès Premium jusqu'à la fin de votre période de facturation en cours. Pas de pénalités, pas de questions." },
    "What happens if I cancel my subscription or leave CryptoOwnBank?": { q: "Que se passe-t-il si j'annule mon abonnement ou quitte CryptoOwnBank ?", a: "Rien n'arrive à votre crypto. C'est tout l'intérêt. Parce que CryptoOwnBank est non-custodial, nous ne détenons jamais vos actifs. Si vous annulez Premium, passez à Free, ou partez entièrement — votre crypto est toujours dans votre wallet, votre position Soil vault continue de générer du rendement, vos trustlines restent actives, et vous pouvez tout accéder via Xaman, votre Ledger, ou tout autre outil compatible XRPL. Vous payez pour le tableau de bord, les analyses, le Recommendations Hub et les outils de trading — pas pour la custodie de vos actifs. Vous pouvez nous quitter et rester en plein contrôle. (Mais nous espérons que vous ne le voudrez pas.)" },
    "Why do BTC, ETH, SOL, XRP, and RLUSD get a bigger discount?": { q: "Pourquoi BTC, ETH, SOL, XRP et RLUSD bénéficient-ils d'une remise plus importante ?", a: "Nous appelons ces cinq notre <strong>House Tier</strong> — payez votre abonnement, add-on ou Legacy Lifetime dans l'un d'eux et vous obtenez la même <strong>remise on-chain plate de 10%</strong> que toute cryptomonnaie prise en charge. House Tier est une désignation de coin préféré, pas une remise supplémentaire. La raison est un alignement honnête de trésorerie : BTC, ETH et SOL sont des actifs blue-chip avec lesquels nous sommes à l'aise de détenir (ils tendent à s'apprécier dans le temps, libellés en dollars qui ne le font pas), et XRP/RLUSD sont notre chaîne d'origine — RLUSD finance littéralement les vaults Soil Protocol qui paient à nos membres 5–8% d'APR. Quand vous nous payez dans ces actifs, vous contribuez effectivement à une trésorerie que nous voulons faire croître plutôt qu'à un payout Stripe que nous devons convertir. Nous vous redistribuons les économies sous forme de remise plus importante.<br/><br/>Les 20 autres cryptomonnaies prises en charge (DOGE, LTC, ADA, AVAX, ATOM, XLM, TON, MATIC, et plus) bénéficient toujours de la remise on-chain standard de 10% versus paiement par carte — elles sont absolument les bienvenues, juste pas dans le house tier.<br/><br/><strong>Founder Badge :</strong> si vous achetez <strong>Legacy Plan Lifetime</strong> dans n'importe quel coin House Tier, votre compte obtient un badge permanent et visible Founding Member indiquant dans quel coin vous avez payé et le mois. C'est notre façon de remercier les membres qui ont mis du vrai Bitcoin, Ether, Solana ou XRP dans la plateforme dès le premier jour." },
    "How safe is my principal?": { q: "Quelle est la sécurité de mon principal ?", a: "Votre principal est protégé de deux façons : 1) Conception non-custodial — les clés ne quittent jamais votre cold wallet. 2) Les Soil vaults sont adossés à des actifs du monde réel (Treasuries, fonds de crédit) avec un underwriting de qualité institutionnelle. Soil publie des APR cibles fixes, mais les rendements ne sont pas garantis — crypto/blockchain comporte toujours des risques (bugs de smart contracts, changements de protocole, événements de marché, risque de contrepartie/RWA). Toujours faire son DYOR." },
    "Can I use Soil vaults without Premium?": { q: "Puis-je utiliser les Soil vaults sans Premium ?", a: "Oui. Connecter votre wallet XRPL, déposer dans les <a href=\"/ownbank/vaults\" class=\"text-[#00A4E4] underline hover:no-underline\">Soil vaults</a>, et <a href=\"/ownbank/withdraw\" class=\"text-[#00A4E4] underline hover:no-underline\">retirer via Soil</a> sont tous gratuits. Premium ajoute le DCA pour la conversion automatique RLUSD vers XRP." },
  },
  tr: {
    "What is CryptoOwnBank?": { q: "CryptoOwnBank nedir?", a: "CryptoOwnBank her şeyin başladığı yerdir — ve bitmez. Kriptonuzun sahibi olun, tek bir arayüzden yönetin, tüm kazancınızı kendinizde tutun. Tüm iş sizin için yapılır: Recommendations Hub kaçıracağınız getirileri öne çıkarır, Statement Insights banka faizlerinizi on-chain ile karşılaştırır, vergi raporları otomatik oluşturulur ve bilgi size gelir. 32+ blockchain'de portföyünüzü takip edin, RLUSD'de 5–8% sabit getiri kazanın, yerel DEX'lerde işlem yapın, küresel ödeme gönderin — anahtarlarınız sizin elinizde kalır. Güvenliğinizi seçin: cold wallet, hot wallet, donanım veya telefon imzası. Bir gün ayrılırsanız, kriptonuz hâlâ cüzdanınızdadır. Ve Legacy Plan, size bir şey olursa kriptonuzun ailenize geçmesini sağlar — yani gerçekten bitmez. Bankasız, debanked veya başarısız olabilecek platformlara güvenmekten yorulmuş olun — CryptoOwnBank size kendi bankanız olmanız için araçları verir." },
    "Why was CryptoOwnBank created? (And why should I use it?)": { q: "CryptoOwnBank neden oluşturuldu? (Ve neden kullanmalıyım?)", a: "CryptoOwnBank, borsaların başarısız olabilmesi, dondurabilmesi veya iflas edebilmesi — ve olduklarında fonlarınızın sıkışması — nedeniyle oluşturuldu. FTX. Celsius. Voyager. Mt. Gox. İnsanlar platformlara milyarlar emanet etti ve o platformlar battı. CryptoOwnBank, kriptonuzun asla başka kimsenin elinde olmaması için vardır. Beş sorunu çözmek için inşa ettik: (1) Tam sahiplik — cüzdanınız kontrolünüzde kalır. Özel anahtarlarınızı asla görmeyiz veya saklamayız. CryptoOwnBank'ten ayrılırsanız bile kriptonuz cüzdanınızda kalır. Asla kilitlenmezsiniz. (2) Kendinizde kalan gerçek getiriler — Soil Protocol üzerinden RLUSD'de 5–8% sabit APR kazanın, her kuruşu tutun. Platform ücreti yok, aracı yok. (3) Sizin koşullarınıza göre güvenlik — cold wallet, hot wallet, donanım veya telefon imzası. Siz seçersiniz. Karar sürecinizde ilgisiz üçüncü taraf yok. (4) Tüm iş sizin için yapılır — Recommendations Hub kaçıracağınız getirileri öne çıkarır, Statement Insights banka faizlerinizi on-chain ile karşılaştırır ve bilgi aramak yerine size gelir. (5) USD fiyatı değil, değer düşünün — dolar her yıl satın alma gücünü kaybeder, ama bir XRP kimin elinde olursa olsun bir XRP'dir. Kriptonuzun daralan bir para biriminde 'ne kadar ettiği'ni değil, ne yapabileceğini görmenize yardımcı oluruz. Her şey burada başlar. Ve bitmez — Legacy Plan (ölü adam anahtarı), size bir şey olursa kriptonuzun ailenize geçmesini sağlar. Bir borsaya değil. Bir iflas mahkemesine değil. Sizin seçtiğiniz kişilere." },
    "Is this a wallet? Do you hold my funds?": { q: "Bu bir cüzdan mı? Fonlarımı siz mi tutuyorsunuz?", a: "Hayır — 10%0 non-custodial'ız. Fonlarınıza veya özel anahtarlarınıza asla sahip olmayız, kontrol etmeyiz veya erişmeyiz. Tüm vault işlemleri (yatırma, çekme) doğrudan kendi cüzdanınızdan imzalanır — cold veya hot, sizin seçiminiz. Portföy takibi için yalnızca herkese açık on-chain verileri okuruz. İşte kritik nokta: CryptoOwnBank yarın yok olsa bile, kriptonuz tam olarak şimdi olduğu yerde olur — cüzdanınızda. İstediğiniz zaman ayrılabilir ve her şeye tam kontrol ve erişiminiz olur. Biz varlıklarınızı tutan bir platform değil, sizin için çalışan bir aracız." },
    "Is this safe? Do you hold my funds?": { q: "Bu güvenli mi? Fonlarımı siz mi tutuyorsunuz?", a: "Hayır — CryptoOwnBank 10%0 non-custodial'dır. Fonlarınıza veya özel anahtarlarınıza asla sahip olmayız, kontrol etmeyiz veya erişmeyiz. Her işlem (trustline değişiklikleri, DEX emirleri, ödemeler) tarayıcınızda oluşturulur ve cold wallet'ınızda (Ledger veya Xumm/Xaman) imzalanır. Bakiyeleri göstermek ve onaylamanız için imzasız işlemler hazırlamak amacıyla yalnızca herkese açık adresinizi okuruz. Sıfır platform riski vardır — CryptoOwnBank yarın yok olsa bile, fonlarınız XRPL blockchain'deki cüzdanınızda güvende kalır." },
    "Do you ever have access to my crypto? What if CryptoOwnBank shuts down?": { q: "Kriptoma hiç erişiminiz oluyor mu? CryptoOwnBank kapanırsa ne olur?", a: "Hayır — hiçbir noktada kriptoya erişimimiz yoktur. 10%0 non-custodial'ız. Özel anahtarlarınızı asla görmeyiz, fonlarınızı asla tutmayız ve varlıklarınızı taşıma yeteneğimiz asla yoktur. Her vault yatırma, çekme, işlem ve ödeme kendi cihazınızda sizin tarafınızdan imzalanır. Bu, CryptoOwnBank ile custodial hizmetler arasındaki temel farktır: bir saklama firması kapanırsa, varlıklarınızı geri almayı uman alacaklılar sırasındasınızdır (herhangi bir FTX müşterisine sorun). CryptoOwnBank yarın kapanırsa, kriptonuz tamamen etkilenmez. Fonlarınız sunucularımızda değil, cüzdanınızdaki blockchain'de yaşar. Cold wallet'ınızı başka herhangi bir XRPL uyumlu uygulamayla kullanmaya devam edebilir, Soil vault pozisyonlarınıza doğrudan Soil Protocol üzerinden erişebilir ve bakiyelerinizi herhangi bir blockchain gezgininde görebilirsiniz. Biz self-custody'nizin üzerindeki bir araç katmanıyız — bir saklamacı değiliz." },
    "Does CryptoOwnBank control my money or make decisions for me?": { q: "CryptoOwnBank paramı kontrol ediyor veya benim yerime karar mı veriyor?", a: "Hayır. Tek bir basit fikir etrafında inşa edildik: her şeyi masaya getiriyoruz ve evet diyen yalnızca sizsiniz. Pratikte bu şunu demektir — (1) Masa biziz: kurmak, incelemek ve harekete geçmek için ihtiyacınız olan her şey tek bir yerde toplanır. (2) Açıklayıcıyız: her adımın ne yaptığını yapmadan önce sade kelimelerle anlatırız. (3) Kontrol listesi ve takipçiyiz: yapılması gereken hiçbir şeyin kaçırılmamasını sağlarız ve sonrasında takip edebilirsiniz. (4) Evet diyen yalnızca sizsiniz: kendi cüzdanınızla onaylayana kadar hiçbir şey olmaz. Paranızı, anahtarlarınızı veya kurtarma ifadenizi asla tutmayız ve kiminle işlem yapmanıza izin verileceğine asla karar vermeyiz. Herkese ve her şeye bağlanmaya çalışmıyoruz — güç bizde değil, sizde ve teknolojide kalır. Sizin için çalışan bir araç ile sizin üzerinizde çalışan bir şirket arasındaki fark budur." },
    "Is CryptoOwnBank a bank, broker, or trust company?": { q: "CryptoOwnBank bir banka, broker veya trust company midir?", a: "Hayır. CryptoOwnBank non-custodial yazılımdır — self-custody cüzdanlar ve on-chain protokoller için bir gösterge paneli ve araç katmanı. Banka, broker-dealer, money transmitter veya trust company değiliz. Varlıklarınızı tutmayız, yatırım getirisi garanti etmeyiz ve yediemin veya miras avukatı olarak hareket etmeyiz. Gördüğünüz getiri rakamları (örneğin Soil vault APR'leri) üçüncü taraf protokollerden gelir ve CryptoOwnBank tarafından garanti edilmez. Legacy Plan, sizin yazdığınız şifreli kurtarma talimatlarını saklar — yasal bir vasiyetname, trust enstrümanı veya saklamalı miras hizmeti değildir." },
    "What is the Legacy Plan (dead-man switch)?": { q: "Legacy Plan (ölü adam anahtarı) nedir?", a: "Legacy Plan, vefatınızdan sonra — veya ehliyetsiz kaldığınızda — kriptonuzu korur. Herhangi bir planda bağımsız eklenti olarak <strong>$29/yr</strong> karşılığında veya <strong>Pro ile ücretsiz dahil</strong> ($99/mo) olarak sunulur. Bu bir ölü adam anahtarıdır: seçtiğiniz bir programa göre check-in yaparsınız (haftalık, iki haftada bir, aylık veya üç aylık). Bir check-in'i kaçırırsanız, bir ekstra süre başlar. Ekstra süre boyunca ikincil kişiniz (eş, avukat vb.) durumunuzu doğrulamak için bilgilendirilir. Ekstra süre yanıtsız sona ererse, lehtarlarınız kurduğunuz cüzdan kurtarma talimatlarını alır — donanım cüzdanınızın nerede saklandığı, seed phrase yedeğinin nerede olduğu, CypheRock 2-of-5 Shamir kurulumuna nasıl erişileceği vb.<br/><br/><strong>ASLA saklamadıklarımız:</strong> seed phrase'ler, özel anahtarlar, şifreler veya PIN'ler. Yalnızca bu şeylerin <em>nerede</em> olduğuna dair SİZİN talimatlarınızı saklarız — 'yangına dayanıklı kasadaki çelik plaka' veya 'Kart 1 avukatta, Kart 3 banka kiralık kasasında.' Her şey dururken şifrelenir ve yalnızca anahtar tetiklendiğinde teslim edilir. Member for Life — kriptonuz sizinle ölmez." },
    "How does the Legacy Plan check-in work?": { q: "Legacy Plan check-in nasıl çalışır?", a: "Legacy Plan gösterge panelinizdeki 'I'm Still Here' düğmesine basarsınız. Hepsi bu — bir tıklama zamanlayıcınızı sıfırlar. Sıklığı siz seçersiniz: haftalık, iki haftada bir, aylık (önerilen) veya üç aylık. Bir check-in'i kaçırırsanız, sistem ekstra süreye girer (varsayılan 14 gün, 90 güne kadar yapılandırılabilir). Ekstra süre boyunca ikincil kişiniz sizinle iletişime geçmeye çalışabilsin diye bilgilendirilir. Ekstra süre sonuna kadar hâlâ check-in yapmazsanız, sistem tetiklenir ve lehtarlarınız talimatlarını alır. İstediğiniz zaman — ekstra süre sırasında bile — check-in yaparak her şeyi normale döndürebilirsiniz." },
    "Is the Legacy Plan really 'Member for Life'?": { q: "Legacy Plan gerçekten 'Member for Life' mı?", a: "Evet — ve ödemenin üç yolu vardır: <strong>$29/yr</strong>, <strong>$99/5yr</strong> veya <strong>$499 once for life</strong>. Pro planı ($99/mo veya $799/yr) Legacy Plan'ı ücretsiz içerir. Hangisini seçerseniz seçin, check-in zamanlayıcısı çalışmaya devam eder, lehtar talimatlarınız şifreli ve hazır kalır ve ölü adam anahtarı her zaman kurulu olur. Aylık veya yıllık abonelik sona ererse, plan duraklatılır (silinmez) — verileriniz korunur, böylece istediğiniz zaman devam edebilirsiniz. Ömür boyu seçenek, üyelerin çoğunun sonunda seçtiği seçenektir; çünkü miras planlamasının bütün noktası, bir kredi kartı süresinin dolmasını, bir bankanın kapanmasını veya unutulmuş bir yenilemeyi aşması gerektiğidir." },
    "What is Split Delivery for the Legacy Plan?": { q: "Legacy Plan için Split Delivery nedir?", a: "Split delivery, e-posta için multi-sig gibidir — bir lehtarın tüm cüzdan kurtarma talimatlarınızı alması yerine, bilgileri birden fazla kişiye bölersiniz, böylece işbirliği yapmak zorunda kalırlar. Örneğin, Kişi A 'Ledger ev ofisi kasasında' alır ve Kişi B 'seed phrase çelik plakası banka kiralık kasası #42'de' alır. Hiçbir kişi tek başına cüzdana erişemez.<br/><br/><strong>All Required</strong> (her lehtarın parçası gerekir) veya <strong>Threshold</strong> (M-of-N, Shamir gibi — örn. herhangi 2-of-3 lehtar tam talimatları yeniden oluşturabilir) seçebilirsiniz. Bu, CypheRock'un 2-of-5 kart sistemiyle mükemmel uyumludur — farklı lehtarlara farklı kart konumları verin. Hiçbir rakip bu tür teslimat düzeyinde bölme sunmaz. Legacy Plan gösterge panelinizdeki tek bir anahtarla etkinleştirin." },
    "What is the Legacy Plan Lifetime ($499 one-time)?": { q: "Legacy Plan Lifetime ($499 one-time) nedir?", a: "Legacy Plan Lifetime, size Legacy Plan'ı sonsuza dek veren $499'lık tek seferlik bir ödemedir (veya 10% on-chain indirimimizle kripto olarak ~$449) — yinelenen ücret yok, süresi dolmuş kart hataları yok, unutulmuş bir aboneliğin planı en çok ihtiyaç duyulduğu anda sona erdirme riski yok. Lifetime, hayatta olduğunuz sürece VE ölü adam anahtarınız ateşlenip kurtarma talimatları lehtarlarınıza bırakıldıktan sonra 12 ay boyunca sizi kapsar. Bu ekstra yıl, hayatta kalanlarınızın sistemi gerçekten kullanması için vardır — e-postaları okumak, SLIP-39 parçalarını /decrypt üzerinde birleştirmek, destek üzerinden soru sormak — yaslarının ortasında erişimi kesmeden.<br/><br/><strong>Miras edilebilirlik:</strong> ömür boyu koltuk tetiklenmede birincil lehtarınıza geçer. Yeni hesap sahibi olarak bizden bir yıl ücretsiz alırlar, sonra kendilerine uyan plana geçerler. Bunun bir kripto miras ürününün yapabileceği en dürüst şey olduğunu düşünüyoruz — gerçekten miras alan kişinin bir paywall değil, çalışan bir hesaba sahip olmasını sağlamak.<br/><br/><strong>Neden inşa ettik:</strong> yinelenen abonelikler, miras planlamasının #1 sessiz hata modudur. İnsanlar bir vasiyetname, bir Legacy Plan, bir lehtar formu kurar — sonra bir kartın süresi dolur, bir banka kapanır, bir e-posta spam'e gider ve her şey sessizce çalışmayı bırakır. Bir kez peşin ödemek bu hata modunu tamamen ortadan kaldırır. Ayrıca çoğu miras planlama avukatının tek bir vasiyet revizyonu için talep ettiğinden önemli ölçüde daha ucuzdur.<br/><br/><strong>Kart veya kripto ile ödeyin:</strong> Stripe üzerinden $499 veya otomatik 10% on-chain indirim için 25 desteklenen kripto paradan herhangi birinde ~$449 (BTC, ETH, XRP, SOL, RLUSD, XLM ve daha fazlası)." },
    "Can the Legacy Plan pre-fill from my connected wallets?": { q: "Legacy Plan bağlı cüzdanlarımdan önceden doldurulabilir mi?", a: "Evet. Bir lehtar ekleyip bir cüzdan türü seçtiğinizde, sistem bağlı cüzdanlarınızı kontrol eder ve hangilerinin o cihazda olabileceğini gösterir. O donanımda olan cüzdanları seçin, 'Load Selected'e tıklayın ve varlık özeti gerçek cüzdan adresleri ve güncel bakiyelerle otomatik doldurulur — böylece hayatta kalanınız her cihazda hangi varlıkların olduğunu tam olarak görür. Kaydetmeden önce özeti düzenleyebilirsiniz. Bu, her cihazda ne olduğunu hatırlamak zorunda olmadığınız anlamına gelir — veriler doğrudan portföyünüzden gelir." },
    "When I connect MetaMask, is my seed phrase or private key shared with CryptoOwnBank?": { q: "MetaMask bağladığımda seed phrase'im veya özel anahtarım CryptoOwnBank ile paylaşılır mı?", a: "Kesinlikle hayır. CryptoOwnBank'te 'Connect Wallet'e tıkladığınızda, MetaMask tarayıcı uzantısı kendi açılır penceresini açar — bu MetaMask'ın arayüzüdür, bizimki değil. MetaMask'ı ilk kez bağlıyorsanız, MetaMask sizden yeni bir cüzdan oluşturmanızı veya kurtarma ifadenizi kullanarak mevcut birini içe aktarmanızı isteyebilir. Tüm bu süreç cihazınızdaki MetaMask uzantısının içinde gerçekleşir. Seed phrase'iniz MetaMask'ın kendi güvenli arayüzüne girilir, şifrelenir ve bilgisayarınızda yerel olarak saklanır — asla CryptoOwnBank'e gönderilmez, asla sunucularımıza iletilmez ve görmenin hiçbir yolu yoktur. MetaMask kurulduktan sonra, yalnızca bir bağlantı isteğini onaylarsınız — MetaMask sitemizle yalnızca herkese açık cüzdan adresinizi paylaşır; bu, herhangi birinin blockchain gezgininde bakabileceği aynı adrestir. Bu adresi bakiyelerinizi göstermek, imzasız işlemler hazırlamak ve swap teklifleri göstermek için kullanırız. Bir swap yürüttüğünüzde veya bir token onayladığınızda, MetaMask tekrar onay istemek için açılır — ve ancak o zaman MetaMask işlemi özel anahtarınızla cihazınızda yerel olarak imzalar. İmzalı işlem doğrudan blockchain'e gider. Hiçbir noktada CryptoOwnBank özel anahtarlarınıza, seed phrase'inize veya imza yetkinize erişmez. Bu, her meşru DeFi uygulamasının kullandığı aynı güvenlik modelidir — Uniswap, Aave, OpenSea — hepsi MetaMask uzantısı üzerinden aynı şekilde çalışır." },
    "Why does CryptoOwnBank warn me when I paste a seed phrase anywhere on the site?": { q: "Sitede herhangi bir yere seed phrase yapıştırdığımda CryptoOwnBank neden beni uyarıyor?", a: "Çünkü hiçbir meşru CryptoOwnBank iş akışı seed phrase'inizi sitemize yazmanızı asla gerektirmez. Nokta. Gerçek bir seed'in görünmesi gereken tek yerler şunlardır: donanım cüzdanınızın kurtarma ekranı, çelik plakanız ve (kısa süreyle, yalnızca tarayıcınızda) SLIP-39 bölücü ve /decrypt birleştirici — her ikisi de tamamen istemci tarafında çalışır ve asla iletmez. <br/><br/>Sitemize 12 veya 24 kelimeyi bir arama çubuğuna, adres alanına, sohbet kutusuna veya başka herhangi bir girişe yapıştırırsanız, sayfa içi bir uyarı hemen durmanızı söyleyerek tetiklenir. Bu, insanların en sık boşaltılma yollarını yakalar — bizimkine benzeyen phishing sayfaları, kopyala-yapıştır kazaları veya sahte 'destek temsilcilerinden' kötü tavsiye. Her şeyi bir anlık kafa karışıklığıyla kaybetmenizi izlemektense sizi bir uyarıyla rahatsız etmeyi tercih ederiz." },
    "Is DCA non-custodial? Who holds my funds?": { q: "DCA non-custodial mı? Fonlarımı kim tutuyor?", a: "10%0 non-custodial. CryptoOwnBank fonlarınızı asla tutmaz, dokunmaz veya erişmez. DCA zamanlayıcısı sunucu tarafında çalışır ve alımınız vadesi geldiğinde bekleyen bir DEX teklifi oluşturur — ancak teklif, siz Xaman veya LOBSTR cüzdanınızda şahsen onaylayana kadar blockchain'e GÖNDERİLMEZ. Özel anahtarlarınız cihazınızı asla terk etmez. Bekleyen bir yürütmeyi onaylamazsanız hiçbir şey olmaz — fonlarınız tam olarak oldukları yerde kalır." },
    "What do I get with Premium?": { q: "Premium ile ne elde ederim?", a: "Premium tam kokpiti açar — kriptonuzun sahibi olun, tek bir arayüzden yönetin, tüm kazancınızı kendinizde tutun. XRPL DEX ticareti (Quick Swap ve Advanced emir defteri ile 44 çift), Stellar DEX ticareti (13 çift), sınırsız borsa bağlantıları, 32+ zincirin tümünde sınırsız blockchain adresleri, tam işlem geçmişi, CSV içe aktarma, sınırsız fiyat uyarıları, aksi takdirde kaçıracağınız fırsatları öne çıkaran kişiselleştirilmiş getiri optimizasyonu ile tam Recommendations Hub, banka faizlerinizi on-chain getirilerle karşılaştıran Statement Insights, özel eşiklerle genişletilmiş Whale Alerts, tüm göstergeler ve 10 yıla kadar grafik verisiyle Technical Analysis ve tuttuğunuz varlıklarla eşleşen makaleleri öne çıkaran kişiselleştirilmiş Crypto News. Tam vergi raporlarının da kilidini açmak için aylık ($29/mo) veya yıllık ($199/yr) seçin. Güvenlik seviyeniz sizin seçiminizdir — cold wallet, hot wallet, donanım veya telefon imzası." },
    "Why should I upgrade to Premium?": { q: "Neden Premium'a yükseltmeliyim?", a: "Kriptonuz birden fazla borsa, cüzdan ve DeFi protokolüne yayılmışsa, Premium size her şeyi görmek için tek bir kokpit verir. Binance, Coinbase, Ledger Live ve Yahoo Finance'e ayrı ayrı giriş yapmak yerine, 32+ blockchain'deki tüm portföyünüzü, on-chain vs custodial netliğiyle kişiselleştirilmiş getiri önerilerini, vergi yükümlülüğünü ve getiri kazançlarını tek bir gösterge panelinde görürsünüz. Recommendations Hub size tam olarak ne kadar getiri kaçırdığınızı ve hangi on-chain fırsatların zaten tuttuğunuz varlıklarla eşleştiğini gösterir." },
    "Can I pay for Premium with crypto?": { q: "Premium'u kripto ile ödeyebilir miyim?", a: "Evet — ve yaptığınızda 10% tasarruf edersiniz. 25 blockchain'de kripto kabul ediyoruz: XRP, RLUSD, BTC, ETH, SOL, XLM, DOGE, LTC, ADA, AVAX, ALGO, ATOM, TRX, HBAR, DOT, VET, TON, MATIC, CRO, XDC, DGB, CSPR, CKB, ZIL ve XVG. Premium $26.10/mo veya $179.10/yr'ye, Pro ise $89.10/mo veya $719.10/yr'ye düşer — hepsi kart fiyatlarından 10% indirimli. Settings → Subscription → Pay with Crypto'ya gidin, zincirinizi seçin; size tam tutarı (CoinGecko üzerinden canlı fiyatlandırılmış) ve gönderilecek cüzdan adresini gösteririz. XRP ve RLUSD için ödemenizi eşleştirmek üzere benzersiz bir destination tag da alırsınız. Sistemimiz ödemenizi on-chain doğrular ve aboneliğinizi hemen etkinleştirir. KYC yok, banka hesabı yok, kredi kartı gerekmez — sadece kripto gönderin ve yükseltmiş olursunuz. Stripe üzerinden kart ödemeleri yedek olarak mevcuttur." },
    "Can I cancel Premium anytime?": { q: "Premium'u istediğim zaman iptal edebilir miyim?", a: "Evet. Aboneliğinizi istediğiniz zaman iptal edebilirsiniz. Mevcut faturalandırma döneminizin sonuna kadar Premium erişiminizi korursunuz. Ceza yok, soru yok." },
    "What happens if I cancel my subscription or leave CryptoOwnBank?": { q: "Aboneliğimi iptal eder veya CryptoOwnBank'ten ayrılırsam ne olur?", a: "Kriptonuza hiçbir şey olmaz. Bütün mesele budur. CryptoOwnBank non-custodial olduğu için varlıklarınızı asla tutmayız. Premium'u iptal ederseniz, Free'ye düşerseniz veya tamamen ayrılırsanız — kriptonuz hâlâ cüzdanınızdadır, Soil vault pozisyonunuz hâlâ getiri kazanmaktadır, trustline'larınız hâlâ aktiftir ve her şeye Xaman, Ledger'ınız veya başka herhangi bir XRPL uyumlu araç üzerinden erişebilirsiniz. Gösterge paneli, analitikler, Recommendations Hub ve ticaret araçları için ödeme yapıyorsunuz — varlıklarınızın saklanması için değil. Bizi bırakıp hâlâ tam kontrolde olabilirsiniz. (Ama istemeyeceğinizi umuyoruz.)" },
    "Why do BTC, ETH, SOL, XRP, and RLUSD get a bigger discount?": { q: "BTC, ETH, SOL, XRP ve RLUSD neden daha büyük indirim alıyor?", a: "Bu beşine <strong>House Tier</strong> diyoruz — aboneliğinizi, eklentinizi veya Legacy Lifetime'ı bunlardan herhangi birinde ödeyin ve desteklenen her kripto para ile aynı düz <strong>10% on-chain indirimi</strong> alın. House Tier tercih edilen coin unvanıdır, ekstra bir indirim değildir. Nedeni dürüst hazine uyumudur: BTC, ETH ve SOL tutmaktan rahat olduğumuz blue-chip varlıklardır (zamanla değer kazanma eğilimindedirler, bunu yapmayan dolar cinsinden), ve XRP/RLUSD ana zincirimizdir — RLUSD kelimenin tam anlamıyla üyelerimize 5–8% APR ödeyen Soil Protocol vault'larını finanse eder. Bize bu varlıklarda ödeme yaptığınızda, dönüştürmemiz gereken bir Stripe ödemesinden ziyade büyütmek istediğimiz bir hazineye katkıda bulunmuş olursunuz. Tasarrufu size daha büyük indirim olarak geri veririz.<br/><br/>Diğer 20 desteklenen kripto para (DOGE, LTC, ADA, AVAX, ATOM, XLM, TON, MATIC ve daha fazlası) hâlâ kart ödemesine karşı standart 10% on-chain indirimi alır — kesinlikle hoş karşılanırlar, sadece house tier'ın parçası değillerdir.<br/><br/><strong>Founder Badge:</strong> herhangi bir House Tier coin'inde <strong>Legacy Plan Lifetime</strong> satın alırsanız, hesabınız hangi coin'de ve hangi ayda ödediğinizi gösteren kalıcı, görünür bir Founding Member rozeti alır. Bu, ilk günden platforma gerçek Bitcoin, Ether, Solana veya XRP koyan üyelere teşekkür etme şeklimizdir." },
    "How safe is my principal?": { q: "Anaparam ne kadar güvende?", a: "Anaparanız iki şekilde korunur: 1) Non-custodial tasarım — anahtarlar cold wallet'ınızı asla terk etmez. 2) Soil vault'ları kurumsal düzeyde underwriting ile gerçek dünya varlıklarıyla (Treasuries, kredi fonları) desteklenir. Soil sabit hedef APR'ler yayınlar, ancak getiriler garanti edilmez — kripto/blockchain her zaman risk taşır (akıllı sözleşme hataları, protokol değişiklikleri, piyasa olayları, karşı taraf/RWA riski). Her zaman DYOR yapın." },
    "Can I use Soil vaults without Premium?": { q: "Premium olmadan Soil vault kullanabilir miyim?", a: "Evet. XRPL cüzdanınızı bağlamak, <a href=\"/ownbank/vaults\" class=\"text-[#00A4E4] underline hover:no-underline\">Soil vault</a>'lara yatırmak ve <a href=\"/ownbank/withdraw\" class=\"text-[#00A4E4] underline hover:no-underline\">Soil üzerinden çekmek</a> tamamen ücretsizdir. Premium, RLUSD'den XRP'ye otomatik dönüşüm için DCA ekler." },
  },
  hi: {
    "What is CryptoOwnBank?": { q: "CryptoOwnBank क्या है?", a: "CryptoOwnBank वह जगह है जहाँ सब कुछ शुरू होता है — और खत्म नहीं होता। अपनी क्रिप्टो के मालिक बनें, एक ही इंटरफ़ेस से प्रबंधित करें, अपनी सारी कमाई अपने पास रखें। सारा काम आपके लिए किया जाता है: Recommendations Hub वे yields दिखाता है जो आप चूक जाते, Statement Insights आपके बैंक rates की तुलना on-chain से करता है, tax reports अपने आप बनते हैं, और जानकारी आपके पास आती है। 32+ blockchains पर अपना portfolio ट्रैक करें, RLUSD पर 5–8% fixed yield कमाएँ, native DEXs पर trade करें, वैश्विक payments भेजें — आपकी keys आपके हाथ में रहती हैं। अपनी सुरक्षा चुनें: cold wallet, hot wallet, hardware या phone signing। अगर आप कभी छोड़ें, आपकी क्रिप्टो अभी भी आपके wallet में है। और Legacy Plan सुनिश्चित करता है कि अगर आपको कुछ हो जाए तो आपकी क्रिप्टो आपके परिवार तक पहुँचे — इसलिए यह सच में खत्म नहीं होता। चाहे आप unbanked हों, debanked हों, या सिर्फ उन platforms पर भरोसा करने से थक गए हों जो fail हो सकते हैं — CryptoOwnBank आपको अपना खुद का बैंक बनने के tools देता है।" },
    "Why was CryptoOwnBank created? (And why should I use it?)": { q: "CryptoOwnBank क्यों बनाया गया? (और मुझे इसे क्यों इस्तेमाल करना चाहिए?)", a: "CryptoOwnBank इसलिए बनाया गया क्योंकि exchanges fail हो सकते हैं, freeze कर सकते हैं, या दिवालिया हो सकते हैं — और जब ऐसा होता है, आपके funds फँस जाते हैं। FTX. Celsius. Voyager. Mt. Gox. लोगों ने platforms पर अरबों का भरोसा किया, और वे platforms fail हो गए। CryptoOwnBank इसलिए है ताकि आपकी क्रिप्टो कभी किसी और के हाथ में न हो। हमने पाँच समस्याओं को हल करने के लिए इसे बनाया: (1) पूर्ण ownership — आपका wallet आपके नियंत्रण में रहता है। हम आपकी private keys कभी नहीं देखते या store करते। भले ही आप CryptoOwnBank छोड़ दें, आपकी क्रिप्टो आपके wallet में रहती है। आप कभी lock-in नहीं होते। (2) असली yields जो आपके पास रहती हैं — Soil Protocol के माध्यम से RLUSD पर 5–8% fixed APR कमाएँ, हर पैसा रखें। कोई platform fees नहीं, कोई middleman नहीं। (3) आपकी शर्तों पर सुरक्षा — cold wallet, hot wallet, hardware या phone signing। आप चुनते हैं। आपके निर्णय प्रक्रिया में कोई उदासीन third party नहीं। (4) सारा काम आपके लिए किया जाता है — Recommendations Hub वे yields दिखाता है जो आप चूक जाते, Statement Insights आपके बैंक rates की तुलना on-chain से करता है, और जानकारी आपके पास आती है बजाय इसके कि आप खोजें। (5) USD price में नहीं, value में सोचें — डॉलर हर साल purchasing power खोता है, लेकिन एक XRP एक XRP है चाहे किसी के भी हाथ में हो। हम आपको यह देखने में मदद करते हैं कि आपकी क्रिप्टो क्या कर सकती है, न कि सिर्फ सिकुड़ती मुद्रा में वह 'कितनी worth' है। यहीं सब कुछ शुरू होता है। और खत्म नहीं होता — Legacy Plan (dead man's switch) सुनिश्चित करता है कि अगर आपको कुछ हो जाए तो आपकी क्रिप्टो आपके परिवार तक पहुँचे। किसी exchange को नहीं। किसी bankruptcy court को नहीं। उन लोगों को जिन्हें आपने चुना।" },
    "Is this a wallet? Do you hold my funds?": { q: "क्या यह एक wallet है? क्या आप मेरे funds रखते हैं?", a: "नहीं — हम 100% non-custodial हैं। हम कभी आपके funds या private keys को hold, control या access नहीं करते। सभी vault actions (deposits, withdrawals) सीधे आपके अपने wallet से sign होती हैं — cold या hot, आपकी पसंद। Portfolio tracking के लिए, हम केवल public on-chain data पढ़ते हैं। मुख्य बात यह है: भले ही CryptoOwnBank कल गायब हो जाए, आपकी क्रिप्टो ठीक वहीं होगी जहाँ अभी है — आपके wallet में। आप कभी भी छोड़ सकते हैं और फिर भी हर चीज़ पर पूरा नियंत्रण और पहुँच रख सकते हैं। हम एक tool हैं जो आपके लिए काम करता है, कोई platform नहीं जो आपके assets को hold करे।" },
    "Is this safe? Do you hold my funds?": { q: "क्या यह सुरक्षित है? क्या आप मेरे funds रखते हैं?", a: "नहीं — CryptoOwnBank 100% non-custodial है। हम कभी आपके funds या private keys को hold, control या access नहीं करते। हर transaction (trustline changes, DEX orders, payments) आपके browser में बनती है और आपके cold wallet (Ledger या Xumm/Xaman) पर sign होती है। हम केवल आपकी public address पढ़ते हैं ताकि balances दिखा सकें और आपके approve करने के लिए unsigned transactions तैयार कर सकें। शून्य platform risk है — भले ही CryptoOwnBank कल गायब हो जाए, आपके funds XRPL blockchain पर आपके wallet में सुरक्षित रहते हैं।" },
    "Do you ever have access to my crypto? What if CryptoOwnBank shuts down?": { q: "क्या आपको कभी मेरी क्रिप्टो तक पहुँच मिलती है? अगर CryptoOwnBank बंद हो जाए तो क्या होगा?", a: "नहीं — किसी भी बिंदु पर हमें आपकी क्रिप्टो तक पहुँच नहीं होती। हम 100% non-custodial हैं। हम कभी आपकी private keys नहीं देखते, कभी आपके funds नहीं रखते, और कभी आपके assets को move करने की क्षमता नहीं रखते। हर vault deposit, withdrawal, trade और payment आपके अपने device पर आपके द्वारा sign किया जाता है। यह CryptoOwnBank और custodial services के बीच मूलभूत अंतर है: अगर कोई custody firm बंद हो जाए, आप creditors की कतार में होते हैं यह उम्मीद करते हुए कि assets वापस मिलें (किसी भी FTX customer से पूछें)। अगर CryptoOwnBank कल बंद हो जाए, आपकी क्रिप्टो पूरी तरह अप्रभावित रहेगी। आपके funds हमारे servers पर नहीं, आपके wallet में blockchain पर रहते हैं। आप किसी भी अन्य XRPL-compatible app के साथ अपना cold wallet इस्तेमाल करना जारी रख सकते हैं, Soil Protocol के माध्यम से सीधे अपने Soil vault positions तक पहुँच सकते हैं, और किसी भी blockchain explorer पर अपने balances देख सकते हैं। हम आपकी self-custody के ऊपर एक tool layer हैं — custodian नहीं।" },
    "Does CryptoOwnBank control my money or make decisions for me?": { q: "क्या CryptoOwnBank मेरे पैसे को नियंत्रित करता है या मेरे लिए निर्णय लेता है?", a: "नहीं। हम एक सरल विचार के इर्द-गिर्द बने हैं: हम सब कुछ मेज़ पर लाते हैं, और हाँ कहने वाले केवल आप हैं। व्यवहार में इसका मतलब है — (1) हम मेज़ हैं: setup, review और act करने के लिए जो कुछ चाहिए वह एक जगह इकट्ठा है। (2) हम समझाने वाले हैं: हर कदम क्या करता है, हम सादे शब्दों में बताते हैं इससे पहले कि आप करें। (3) हम checklist और tracker हैं: सुनिश्चित करते हैं कि जो करना है वह न छूटे, और आप बाद में follow कर सकें। (4) हाँ कहने वाले केवल आप हैं: जब तक आप अपने wallet से approve नहीं करते, कुछ नहीं होता। हम कभी आपका पैसा, आपकी keys या आपकी recovery phrase नहीं रखते, और कभी यह तय नहीं करते कि आप किससे deal कर सकते हैं। हम सबके और हर चीज़ के साथ जुड़ने की कोशिश नहीं कर रहे — शक्ति हमारे पास नहीं, आपके और technology के पास रहती है। यही अंतर है एक tool जो आपके लिए काम करता है और एक कंपनी जो आपके ऊपर काम करती है।" },
    "Is CryptoOwnBank a bank, broker, or trust company?": { q: "क्या CryptoOwnBank एक बैंक, broker या trust company है?", a: "नहीं। CryptoOwnBank non-custodial software है — self-custody wallets और on-chain protocols के लिए एक dashboard और tooling layer। हम बैंक, broker-dealer, money transmitter या trust company नहीं हैं। हम आपके assets नहीं रखते, investment returns की गारंटी नहीं देते, और fiduciary या estate attorney के रूप में काम नहीं करते। जो yield figures आप देखते हैं (उदाहरण के लिए Soil vault APRs) third-party protocols से आती हैं और CryptoOwnBank द्वारा guaranteed नहीं हैं। Legacy Plan आपके लिखे encrypted recovery instructions store करता है — यह कानूनी will, trust instrument या custodial inheritance service नहीं है।" },
    "What is the Legacy Plan (dead-man switch)?": { q: "Legacy Plan (dead-man switch) क्या है?", a: "Legacy Plan आपके निधन के बाद — या अगर आप अक्षम हो जाएँ — आपकी क्रिप्टो की रक्षा करता है। यह किसी भी tier पर standalone add-on के रूप में <strong>$29/yr</strong> पर उपलब्ध है, या <strong>Pro के साथ मुफ़्त शामिल</strong> ($99/mo)। यह एक dead-man switch है: आप अपनी चुनी schedule पर check-in करते हैं (साप्ताहिक, द्विसाप्ताहिक, मासिक या त्रैमासिक)। अगर आप एक check-in चूक जाते हैं, grace period शुरू होती है। Grace period के दौरान, आपके secondary contact (पति/पत्नी, attorney आदि) को आपकी स्थिति सत्यापित करने के लिए सूचित किया जाता है। अगर बिना जवाब के grace period समाप्त हो जाती है, आपके beneficiaries को आपके सेट किए wallet recovery instructions मिलते हैं — आपका hardware wallet कहाँ रखा है, seed phrase backup कहाँ है, CypheRock 2-of-5 Shamir setup कैसे एक्सेस करें, आदि।<br/><br/><strong>हम जो कभी STORE नहीं करते:</strong> seed phrases, private keys, passwords या PINs। हम केवल इस बारे में आपके instructions store करते हैं कि वे चीज़ें <em>कहाँ</em> हैं — 'fireproof safe में steel plate' या 'Card 1 attorney के पास, Card 3 bank safe deposit box में।' सब कुछ at rest encrypted है और केवल तभी deliver होता है जब switch trigger हो। Member for Life — आपकी क्रिप्टो आपके साथ नहीं मरती।" },
    "How does the Legacy Plan check-in work?": { q: "Legacy Plan check-in कैसे काम करता है?", a: "आप अपने Legacy Plan dashboard पर 'I'm Still Here' बटन दबाते हैं। बस इतना — एक क्लिक आपका timer reset करता है। आप चुनते हैं कितनी बार: साप्ताहिक, द्विसाप्ताहिक, मासिक (अनुशंसित), या त्रैमासिक। अगर आप एक check-in चूक जाते हैं, सिस्टम grace period में जाता है (डिफ़ॉल्ट 14 दिन, 90 दिन तक configurable)। Grace के दौरान, आपके secondary contact को सूचित किया जाता है ताकि वे आपसे संपर्क करने की कोशिश कर सकें। अगर grace period के अंत तक भी आप check-in नहीं करते, सिस्टम trigger होता है और आपके beneficiaries को उनके instructions मिलते हैं। आप कभी भी check-in कर सकते हैं — grace period के दौरान भी — सब कुछ सामान्य पर reset करने के लिए।" },
    "Is the Legacy Plan really 'Member for Life'?": { q: "क्या Legacy Plan सच में 'Member for Life' है?", a: "हाँ — और भुगतान के तीन तरीके हैं: <strong>$29/yr</strong>, <strong>$99/5yr</strong>, या <strong>$499 once for life</strong>। Pro tier ($99/mo या $799/yr) में Legacy Plan मुफ़्त शामिल है। जो भी चुनें, check-in timer चलता रहता है, आपके beneficiary instructions encrypted और तैयार रहते हैं, और dead-man switch हमेशा armed रहता है। अगर मासिक या वार्षिक subscription lapse हो जाए, plan pause होता है (delete नहीं) — आपका data सुरक्षित रहता है ताकि आप कभी भी resume कर सकें। Lifetime विकल्प वही है जो अधिकांश members अंततः चुनते हैं जब उन्हें एहसास होता है कि estate planning का पूरा उद्देश्य यह है कि वह credit card expiry, bank closure या भूली renewal से अधिक समय तक चले।" },
    "What is Split Delivery for the Legacy Plan?": { q: "Legacy Plan के लिए Split Delivery क्या है?", a: "Split delivery email के लिए multi-sig जैसा है — एक beneficiary को आपके सारे wallet recovery instructions मिलने के बजाय, आप जानकारी कई लोगों में बाँटते हैं ताकि उन्हें सहयोग करना पड़े। उदाहरण के लिए, Person A को मिलता है 'Ledger home office safe में है' और Person B को 'seed phrase steel plate bank safe deposit box #42 में है।' अकेले कोई भी व्यक्ति wallet तक पहुँच नहीं सकता।<br/><br/>आप <strong>All Required</strong> (हर beneficiary का हिस्सा ज़रूरी) या <strong>Threshold</strong> (M-of-N, Shamir जैसा — जैसे कोई भी 2-of-3 beneficiaries पूर्ण instructions reconstruct कर सकते हैं) चुन सकते हैं। यह CypheRock के 2-of-5 card system के साथ पूरी तरह मेल खाता है — अलग beneficiaries को अलग card locations दें। कोई भी competitor इस तरह delivery-level splitting नहीं देता। अपने Legacy Plan dashboard पर एक toggle से सक्षम करें।" },
    "What is the Legacy Plan Lifetime ($499 one-time)?": { q: "Legacy Plan Lifetime ($499 one-time) क्या है?", a: "Legacy Plan Lifetime $499 का एकमुश्त भुगतान है (या हमारे 10% on-chain discount के साथ क्रिप्टो में ~$449) जो आपको हमेशा के लिए Legacy Plan देता है — कोई recurring charges नहीं, कोई expired-card failures नहीं, कोई जोखिम नहीं कि भूली subscription ठीक तब plan lapse करा दे जब सबसे ज़्यादा ज़रूरत हो। Lifetime आपको तब तक कवर करता है जब तक आप जीवित हैं और आपके dead-man switch के fire होने तथा recovery instructions आपके beneficiaries को release होने के बाद 12 महीने तक। वह अतिरिक्त वर्ष इसलिए है ताकि आपके survivors के पास सिस्टम वाकई इस्तेमाल करने का समय हो — emails पढ़ना, /decrypt पर SLIP-39 shards combine करना, support से सवाल पूछना — बिना उनके शोक के बीच में access छीने।<br/><br/><strong>Inheritability:</strong> lifetime seat trigger पर आपके primary beneficiary को जाता है। उन्हें नए account-holder के रूप में हमसे एक वर्ष मुफ़्त मिलता है, फिर वे जो tier उपयुक्त हो उसमें convert करते हैं। हम सोचते हैं कि यह क्रिप्टो inheritance product का सबसे ईमानदार काम है — सुनिश्चित करना कि जो व्यक्ति वाकई inherit करे उसके पास working account हो, paywall नहीं।<br/><br/><strong>हमने क्यों बनाया:</strong> recurring subscriptions estate planning का #1 silent failure mode हैं। लोग will, Legacy Plan, beneficiary form सेट करते हैं — फिर card expire होता है, bank बंद होता है, email spam में जाता है, और सब चुपचाप काम करना बंद कर देता है। एक बार pre-pay करने से वह failure mode पूरी तरह हट जाता है। यह अधिकांश estate-planning lawyers के एक will revision के शुल्क से भी काफी सस्ता है।<br/><br/><strong>Card या crypto से भुगतान:</strong> Stripe के ज़रिए $499, या स्वचालित 10% on-chain discount के लिए 25 supported cryptocurrencies में से किसी में ~$449 (BTC, ETH, XRP, SOL, RLUSD, XLM, और अधिक)।" },
    "Can the Legacy Plan pre-fill from my connected wallets?": { q: "क्या Legacy Plan मेरे connected wallets से pre-fill हो सकता है?", a: "हाँ। जब आप beneficiary जोड़ते हैं और wallet type चुनते हैं, सिस्टम आपके connected wallets जाँचता है और दिखाता है कि कौन से उस device पर हो सकते हैं। उस hardware पर जो wallets हैं उन्हें चुनें, 'Load Selected' क्लिक करें, और asset summary वास्तविक wallet addresses और वर्तमान balances से auto-fill हो जाता है — ताकि आपका survivor ठीक-ठीक देखे कि हर device पर कौन से assets हैं। Save करने से पहले आप summary edit कर सकते हैं। इसका मतलब है कि आपको याद रखने की ज़रूरत नहीं कि हर device पर क्या है — data सीधे आपके portfolio से आता है।" },
    "When I connect MetaMask, is my seed phrase or private key shared with CryptoOwnBank?": { q: "जब मैं MetaMask connect करता हूँ, क्या मेरी seed phrase या private key CryptoOwnBank के साथ share होती है?", a: "बिल्कुल नहीं। जब आप CryptoOwnBank पर 'Connect Wallet' क्लिक करते हैं, MetaMask browser extension अपना खुद का popup खोलता है — यह MetaMask का interface है, हमारा नहीं। अगर आप पहली बार MetaMask connect कर रहे हैं, MetaMask आपसे नया wallet बनाने या अपनी recovery phrase से मौजूदा import करने को कह सकता है। वह पूरी प्रक्रिया आपके device पर MetaMask extension के अंदर होती है। आपकी seed phrase MetaMask के अपने secure interface में enter होती है, encrypt होती है, और आपके computer पर locally store होती है — यह कभी CryptoOwnBank को नहीं भेजी जाती, कभी हमारे servers पर transmit नहीं होती, और हमें उसे देखने का कोई तरीका नहीं है। MetaMask setup के बाद, आप बस एक connection request approve करते हैं — MetaMask हमारे site के साथ केवल आपकी public wallet address share करता है, वही address जो कोई भी blockchain explorer पर देख सकता है। हम उस address का उपयोग आपके balances दिखाने, unsigned transactions तैयार करने और swap quotes दिखाने के लिए करते हैं। जब आप swap execute करते हैं या token approve करते हैं, MetaMask फिर confirm माँगता है — और तभी MetaMask आपके device पर locally आपकी private key से transaction sign करता है। Signed transaction सीधे blockchain पर जाती है। किसी भी बिंदु पर CryptoOwnBank के पास आपकी private keys, seed phrase या signing authority तक पहुँच नहीं होती। यही security model हर वैध DeFi app इस्तेमाल करता है — Uniswap, Aave, OpenSea — सब MetaMask extension के माध्यम से उसी तरह काम करते हैं।" },
    "Why does CryptoOwnBank warn me when I paste a seed phrase anywhere on the site?": { q: "जब मैं site पर कहीं भी seed phrase paste करता हूँ तो CryptoOwnBank मुझे क्यों चेतावनी देता है?", a: "क्योंकि कोई भी वैध CryptoOwnBank workflow कभी आपकी seed phrase हमारे site पर type करने की माँग नहीं करता। पूर्ण विराम। जहाँ एक असली seed दिखाई देनी चाहिए वे जगहें केवल हैं: आपके hardware wallet की recovery screen, आपकी steel plate, और (संक्षेप में, केवल आपके browser में) SLIP-39 splitter और /decrypt combiner — दोनों पूरी तरह client-side चलते हैं और कभी transmit नहीं करते। <br/><br/>अगर आप हमारे site पर search bar, address field, chat box या किसी अन्य input में 12 या 24 शब्द paste करते हैं, एक in-page warning तुरंत रुकने को कहती है। यह उन सबसे आम तरीकों को पकड़ता है जिनसे लोग drain होते हैं — phishing pages जो हमारी जैसी दिखती हैं, copy-paste accidents, या scam 'support agents' की बुरी सलाह। हम एक पल की confusion में सब खोते देखने से बेहतर एक warning से परेशान करना पसंद करते हैं।" },
    "Is DCA non-custodial? Who holds my funds?": { q: "क्या DCA non-custodial है? मेरे funds कौन रखता है?", a: "100% non-custodial। CryptoOwnBank कभी आपके funds को hold, touch या access नहीं करता। DCA scheduler server-side चलता है और जब आपकी buy due होती है तो एक pending DEX offer बनाता है — लेकिन offer blockchain पर SUBMIT नहीं होता जब तक आप व्यक्तिगत रूप से अपने Xaman या LOBSTR wallet में उसे approve न करें। आपकी private keys कभी आपके device को नहीं छोड़तीं। अगर आप pending execution approve नहीं करते, कुछ नहीं होता — आपके funds ठीक वहीं रहते हैं जहाँ हैं।" },
    "What do I get with Premium?": { q: "Premium के साथ मुझे क्या मिलता है?", a: "Premium पूरा cockpit unlock करता है — अपनी क्रिप्टो के मालिक बनें, एक ही इंटरफ़ेस से प्रबंधित करें, अपनी सारी कमाई रखें। XRPL DEX trading (Quick Swap और Advanced order book के साथ 44 pairs), Stellar DEX trading (13 pairs), unlimited exchange connections, सभी 32+ chains पर unlimited blockchain addresses, पूरा transaction history, CSV import, unlimited price alerts, personalized yield optimization के साथ पूरा Recommendations Hub जो वे opportunities दिखाता है जो आप अन्यथा चूक जाते, Statement Insights जो आपके बैंक rates की तुलना on-chain yields से करते हैं, custom thresholds के साथ extended Whale Alerts, सभी indicators और 10 साल तक chart data के साथ Technical Analysis, और personalized Crypto News जो आपके पास मौजूद assets से मेल खाते articles दिखाता है। पूरा tax reports भी unlock करने के लिए मासिक ($29/mo) या वार्षिक ($199/yr) चुनें। आपका security level आपकी पसंद है — cold wallet, hot wallet, hardware या phone signing।" },
    "Why should I upgrade to Premium?": { q: "मुझे Premium में upgrade क्यों करना चाहिए?", a: "अगर आपकी क्रिप्टो कई exchanges, wallets और DeFi protocols में फैली है, Premium आपको सब कुछ देखने के लिए एक cockpit देता है। Binance, Coinbase, Ledger Live और Yahoo Finance में अलग-अलग login करने के बजाय, आप 32+ blockchains पर अपना पूरा portfolio, on-chain vs custodial clarity के साथ personalized yield recommendations, tax liability और yield earnings एक ही dashboard में देखते हैं। Recommendations Hub आपको ठीक दिखाता है कि आप कितनी yield miss कर रहे हैं और कौन सी on-chain opportunities आपके पास पहले से मौजूद assets से मेल खाती हैं।" },
    "Can I pay for Premium with crypto?": { q: "क्या मैं Premium क्रिप्टो से भुगतान कर सकता हूँ?", a: "हाँ — और ऐसा करने पर आप 10% बचाते हैं। हम 25 blockchains पर क्रिप्टो स्वीकार करते हैं: XRP, RLUSD, BTC, ETH, SOL, XLM, DOGE, LTC, ADA, AVAX, ALGO, ATOM, TRX, HBAR, DOT, VET, TON, MATIC, CRO, XDC, DGB, CSPR, CKB, ZIL और XVG। Premium $26.10/mo या $179.10/yr पर आता है, और Pro $89.10/mo या $719.10/yr पर — सब card prices से 10% कम। Settings → Subscription → Pay with Crypto पर जाएँ, अपनी chain चुनें, और हम आपको exact amount (CoinGecko के ज़रिए live priced) और भेजने के लिए wallet address दिखाते हैं। XRP और RLUSD के लिए, आपको अपना payment match करने के लिए एक unique destination tag भी मिलता है। हमारा सिस्टम आपके payment को on-chain verify करता है और तुरंत आपकी subscription activate करता है। कोई KYC नहीं, कोई bank account नहीं, कोई credit card नहीं — बस क्रिप्टो भेजें और आप upgraded हैं। Stripe के ज़रिए card payments fallback के रूप में उपलब्ध हैं।" },
    "Can I cancel Premium anytime?": { q: "क्या मैं कभी भी Premium cancel कर सकता हूँ?", a: "हाँ। आप कभी भी अपनी subscription cancel कर सकते हैं। आप अपनी वर्तमान billing period के अंत तक Premium access रखेंगे। कोई penalties नहीं, कोई सवाल नहीं।" },
    "What happens if I cancel my subscription or leave CryptoOwnBank?": { q: "अगर मैं अपनी subscription cancel करूँ या CryptoOwnBank छोड़ दूँ तो क्या होगा?", a: "आपकी क्रिप्टो के साथ कुछ नहीं होता। यही पूरा बिंदु है। क्योंकि CryptoOwnBank non-custodial है, हम कभी आपके assets नहीं रखते। अगर आप Premium cancel करें, Free पर downgrade करें, या पूरी तरह छोड़ दें — आपकी क्रिप्टो अभी भी आपके wallet में है, आपकी Soil vault position अभी भी yield कमा रही है, आपकी trustlines अभी भी active हैं, और आप Xaman, अपने Ledger या किसी भी अन्य XRPL-compatible tool के माध्यम से सब कुछ एक्सेस कर सकते हैं। आप dashboard, analytics, Recommendations Hub और trading tools के लिए भुगतान कर रहे हैं — अपने assets की custody के लिए नहीं। आप हमें छोड़ सकते हैं और फिर भी पूर्ण नियंत्रण में रह सकते हैं। (लेकिन हम उम्मीद करते हैं कि आप नहीं चाहेंगे।)" },
    "Why do BTC, ETH, SOL, XRP, and RLUSD get a bigger discount?": { q: "BTC, ETH, SOL, XRP और RLUSD को बड़ा discount क्यों मिलता है?", a: "हम उन पाँच को अपना <strong>House Tier</strong> कहते हैं — उनमें से किसी में अपनी subscription, add-on या Legacy Lifetime का भुगतान करें और हर supported cryptocurrency के समान flat <strong>10% on-chain discount</strong> पाएँ। House Tier एक preferred-coin designation है, अतिरिक्त discount नहीं। कारण ईमानदार treasury alignment है: BTC, ETH और SOL blue-chip assets हैं जिन्हें रखने में हम सहज हैं (वे समय के साथ appreciate होते हैं, उन डॉलर में denominated जो नहीं करते), और XRP/RLUSD हमारी home chain हैं — RLUSD सच में उन Soil Protocol vaults को fund करता है जो हमारे members को 5–8% APR देते हैं। जब आप हमें उन assets में भुगतान करते हैं, आप प्रभावी रूप से उस treasury में योगदान दे रहे हैं जिसे हम बढ़ाना चाहते हैं बजाय Stripe payout के जिसे हमें convert करना पड़ता है। हम बचत आपको बड़े discount के रूप में वापस देते हैं।<br/><br/>अन्य 20 supported cryptocurrencies (DOGE, LTC, ADA, AVAX, ATOM, XLM, TON, MATIC, और अधिक) अभी भी card payment के मुकाबले standard 10% on-chain discount पाती हैं — वे पूरी तरह welcome हैं, बस house tier का हिस्सा नहीं।<br/><br/><strong>Founder Badge:</strong> अगर आप किसी भी House Tier coin में <strong>Legacy Plan Lifetime</strong> खरीदते हैं, आपके account को एक permanent visible Founding Member badge मिलता है जो दिखाता है कि आपने किस coin में और किस महीने भुगतान किया। यह उन members का धन्यवाद करने का हमारा तरीका है जिन्होंने दिन एक से platform में असली Bitcoin, Ether, Solana या XRP डाला।" },
    "How safe is my principal?": { q: "मेरा principal कितना सुरक्षित है?", a: "आपका principal दो तरीकों से सुरक्षित है: 1) Non-custodial design — keys कभी आपके cold wallet को नहीं छोड़तीं। 2) Soil vaults वास्तविक दुनिया के assets (Treasuries, credit funds) से backed हैं, institutional-grade underwriting के साथ। Soil fixed target APRs प्रकाशित करता है, लेकिन returns guaranteed नहीं हैं — crypto/blockchain हमेशा जोखिम रखता है (smart contract bugs, protocol changes, market events, counterparty/RWA risk)। हमेशा DYOR करें।" },
    "Can I use Soil vaults without Premium?": { q: "क्या मैं Premium के बिना Soil vaults इस्तेमाल कर सकता हूँ?", a: "हाँ। अपना XRPL wallet connect करना, <a href=\"/ownbank/vaults\" class=\"text-[#00A4E4] underline hover:no-underline\">Soil vaults</a> में deposit करना, और <a href=\"/ownbank/withdraw\" class=\"text-[#00A4E4] underline hover:no-underline\">Soil के ज़रिए withdraw</a> करना सब मुफ़्त है। Premium RLUSD-to-XRP automatic conversion के लिए DCA जोड़ता है।" },
  },
  zh: {
    "What is CryptoOwnBank?": { q: "什么是 CryptoOwnBank？", a: "CryptoOwnBank 是一切开始的地方——而且不会结束。拥有你的加密资产，从一个界面管理，保留全部收益。所有工作都为你完成：Recommendations Hub 会呈现你可能错过的收益，Statement Insights 对比你的银行利率与链上收益，税务报告自动生成，信息主动送达。跨 32+ 条区块链追踪投资组合，在 RLUSD 上赚取 5–8% 固定收益，在原生 DEX 上交易，全球汇款——密钥始终在你手中。选择你的安全方式：冷钱包、热钱包、硬件或手机签名。如果你离开，加密资产仍在你的钱包里。而 Legacy Plan 确保若发生意外，你的加密资产会传给家人——因此它真正不会结束。无论你是无银行服务者、被银行拒绝者，还是厌倦了信任可能失败的平台——CryptoOwnBank 给你成为自己银行的工具。" },
    "Why was CryptoOwnBank created? (And why should I use it?)": { q: "为什么创建 CryptoOwnBank？（我为什么要用它？）", a: "创建 CryptoOwnBank 是因为交易所可能失败、冻结或破产——一旦发生，你的资金就被困住。FTX。Celsius。Voyager。Mt. Gox。人们把数十亿托付给平台，而这些平台失败了。CryptoOwnBank 的存在是为了让你的加密资产永不落入他人之手。我们为解决五个问题而构建：（1）完全所有权——钱包始终由你控制。我们从不查看或存储你的私钥。即使你离开 CryptoOwnBank，加密资产仍在你的钱包中。你永不被锁定。（2）你能留住的真实收益——通过 Soil Protocol 在 RLUSD 上赚取 5–8% 固定 APR，每一分都归你。无平台费，无中间商。（3）按你的条件保障安全——冷钱包、热钱包、硬件或手机签名。由你选择。决策过程中没有冷漠的第三方。（4）所有工作都为你完成——Recommendations Hub 呈现你可能错过的收益，Statement Insights 对比银行利率与链上收益，信息主动送达而不是让你去找。（5）用价值思考，而非美元价格——美元每年都在失去购买力，但一枚 XRP 无论在谁手里都是一枚 XRP。我们帮你看清加密资产能做什么，而不只是它在缩水货币中的「价值」。一切从这里开始。而且不会结束——Legacy Plan（死人开关）确保若发生意外，你的加密资产传给家人。不是交易所。不是破产法庭。而是你选择的人。" },
    "Is this a wallet? Do you hold my funds?": { q: "这是钱包吗？你们代持我的资金吗？", a: "不——我们是 100% 非托管的。我们从不持有、控制或访问你的资金或私钥。所有金库操作（存入、取出）都直接由你自己的钱包签名——冷钱包或热钱包，由你选择。投资组合追踪仅读取公开链上数据。关键在于：即使 CryptoOwnBank 明天消失，你的加密资产仍会在它现在的位置——你的钱包里。你可以随时离开，并仍对一切拥有完全控制与访问权。我们是为你服务的工具，不是持有你资产的平台。" },
    "Is this safe? Do you hold my funds?": { q: "这安全吗？你们代持我的资金吗？", a: "不——CryptoOwnBank 是 100% 非托管的。我们从不持有、控制或访问你的资金或私钥。每笔交易（信任线变更、DEX 订单、支付）都在你的浏览器中构建，并在你的冷钱包（Ledger 或 Xumm/Xaman）上签名。我们仅读取你的公开地址以显示余额，并准备未签名交易供你批准。平台风险为零——即使 CryptoOwnBank 明天消失，你的资金仍安全地留在 XRPL 区块链上的钱包中。" },
    "Do you ever have access to my crypto? What if CryptoOwnBank shuts down?": { q: "你们会接触到我的加密资产吗？如果 CryptoOwnBank 关闭会怎样？", a: "不会——我们在任何时候都无法访问你的加密资产。我们是 100% 非托管的。我们从不查看你的私钥，从不持有你的资金，也从未有能力转移你的资产。每一笔金库存入、取出、交易和支付都由你在自己的设备上签名。这就是 CryptoOwnBank 与托管服务的根本区别：如果托管公司关闭，你排在债权人队伍中希望拿回资产（问问任何 FTX 客户）。如果 CryptoOwnBank 明天关闭，你的加密资产完全不受影响。你的资金存在于区块链上的钱包中，而不是我们的服务器上。你可以继续用任何其他 XRPL 兼容应用使用冷钱包，通过 Soil Protocol 直接访问 Soil 金库仓位，并在任何区块链浏览器上查看余额。我们是你自托管之上的工具层——不是托管方。" },
    "Does CryptoOwnBank control my money or make decisions for me?": { q: "CryptoOwnBank 会控制我的资金或替我做决定吗？", a: "不会。我们围绕一个简单理念构建：我们把一切摆上桌面，只有你说「是」。实际意味着——（1）我们是桌面：你需要的设置、审查与行动都集中在一处。（2）我们是讲解者：在你操作前用白话告诉你每一步做什么。（3）我们是清单与追踪器：确保该做的事不会遗漏，之后你可以跟进。（4）只有你说「是」：在你用自己的钱包批准之前，什么都不会发生。我们从不持有你的资金、密钥或恢复短语，也从不决定你被允许与谁交易。我们并不试图接入所有人与所有事——权力留在你和技术手中，而不是我们。这就是为你服务的工具与对你动手脚的公司之间的区别。" },
    "Is CryptoOwnBank a bank, broker, or trust company?": { q: "CryptoOwnBank 是银行、券商还是信托公司吗？", a: "不是。CryptoOwnBank 是非托管软件——面向自托管钱包与链上协议的仪表盘与工具层。我们不是银行、经纪自营商、货币传输机构或信托公司。我们不持有你的资产，不保证投资回报，也不充当受托人或遗产律师。你看到的收益数字（例如 Soil 金库 APR）来自第三方协议，并非由 CryptoOwnBank 保证。Legacy Plan 存储你撰写的加密恢复说明——它不是法律遗嘱、信托文书或托管继承服务。" },
    "What is the Legacy Plan (dead-man switch)?": { q: "什么是 Legacy Plan（死人开关）？", a: "Legacy Plan 在你去世后——或你丧失行为能力时——保护你的加密资产。可在任何档位以独立附加服务购买，价格为 <strong>$29/yr</strong>，或 <strong>随 Pro 免费包含</strong>（$99/mo）。它是一个死人开关：你按自选节奏签到（每周、双周、每月或每季度）。若错过签到，宽限期开始。宽限期内，会通知你的次要联系人（配偶、律师等）核实你的状态。若宽限期结束仍无回应，受益人将收到你设置的钱包恢复说明——硬件钱包存放位置、助记词备份位置、如何访问 CypheRock 2-of-5 Shamir 设置等。<br/><br/><strong>我们绝不存储：</strong>助记词、私钥、密码或 PIN。我们只存储你关于这些东西<em>在哪里</em>的说明——「防火保险柜里的钢板」或「卡 1 在律师处，卡 3 在银行保险箱」。一切静态加密，仅在开关触发时交付。Member for Life——你的加密资产不会随你消亡。" },
    "How does the Legacy Plan check-in work?": { q: "Legacy Plan 签到如何运作？", a: "你在 Legacy Plan 仪表盘上按下「I'm Still Here」按钮。就这样——一点即可重置计时器。你选择频率：每周、双周、每月（推荐）或每季度。若错过签到，系统进入宽限期（默认 14 天，可配置至 90 天）。宽限期内会通知你的次要联系人以便联系你。若宽限期结束你仍未签到，系统触发，受益人收到其说明。你可以随时签到——即使在宽限期内——以将一切重置为正常。" },
    "Is the Legacy Plan really 'Member for Life'?": { q: "Legacy Plan 真的是「Member for Life」吗？", a: "是的——你有三种付费方式：<strong>$29/yr</strong>、<strong>$99/5yr</strong>，或 <strong>$499 once for life</strong>。Pro 档位（$99/mo 或 $799/yr）免费包含 Legacy Plan。无论你选择哪一种，签到计时器持续运行，受益人说明保持加密就绪，死人开关始终待命。若月付或年付订阅失效，计划会暂停（不会删除）——数据保留，以便你随时恢复。多数会员最终会选择终身选项，因为他们意识到遗产规划的全部意义在于它应比信用卡过期、银行关闭或遗忘续费更长久。" },
    "What is Split Delivery for the Legacy Plan?": { q: "Legacy Plan 的 Split Delivery 是什么？", a: "分拆交付就像邮件版的多签——不是让一名受益人收到全部钱包恢复说明，而是把信息拆分给多人，迫使他们协作。例如，A 收到「Ledger 在家庭办公室保险柜」，B 收到「助记词钢板在银行保险箱 #42」。任何单人都无法单独访问钱包。<br/><br/>你可以选择 <strong>All Required</strong>（需要每位受益人的片段）或 <strong>Threshold</strong>（M-of-N，如 Shamir——例如任意 2-of-3 受益人可重建完整说明）。这与 CypheRock 的 2-of-5 卡片系统完美搭配——把不同卡片位置交给不同受益人。没有竞争对手提供这种交付级拆分。在 Legacy Plan 仪表盘上用一个开关启用。" },
    "What is the Legacy Plan Lifetime ($499 one-time)?": { q: "什么是 Legacy Plan Lifetime（$499 一次性）？", a: "Legacy Plan Lifetime 是一次性支付 $499（或使用我们的 10% 链上折扣以加密支付~$449），让你永久拥有 Legacy Plan——无经常性费用，无过期卡失败，无因遗忘订阅而在最需要时计划失效的风险。Lifetime覆盖你生前，以及死人开关触发、恢复说明释放给受益人之后的 12 个月。这额外一年是为了让幸存者有时间真正使用系统——阅读邮件、在 /decrypt 合并 SLIP-39 分片、通过支持提问——而不会在哀悼中途被切断访问。<br/><br/><strong>可继承性：</strong>终身席位在触发时传给主要受益人。他们作为新账户持有人获得我们提供的一年免费，然后转为适合他们的档位。我们认为这是加密继承产品能做的最诚实的事——确保真正继承的人拥有可用账户，而不是付费墙。<br/><br/><strong>我们为何构建：</strong>经常性订阅是遗产规划的第一大静默失败模式。人们设置遗嘱、Legacy Plan、受益人表格——然后卡过期、银行关闭、邮件进垃圾箱，整件事悄悄停止工作。一次性预付彻底消除该失败模式。它也显著低于多数遗产规划律师单次遗嘱修订的收费。<br/><br/><strong>用卡或加密支付：</strong>通过 Stripe 支付 $499，或在 25 种支持的加密货币中任选其一支付~$449（BTC、ETH、XRP、SOL、RLUSD、XLM 等）自动享受 10% 链上折扣。" },
    "Can the Legacy Plan pre-fill from my connected wallets?": { q: "Legacy Plan 能否从我已连接的钱包预填？", a: "可以。当你添加受益人并选择钱包类型时，系统会检查已连接钱包，并显示哪些可能在该设备上。选择该硬件上的钱包，点击「Load Selected」，资产摘要会自动填入实际钱包地址与当前余额——让幸存者准确看到每台设备上有哪些资产。保存前可编辑摘要。这意味着你不必记住每台设备上有什么——数据直接来自你的投资组合。" },
    "When I connect MetaMask, is my seed phrase or private key shared with CryptoOwnBank?": { q: "连接 MetaMask 时，我的助记词或私钥会与 CryptoOwnBank 共享吗？", a: "绝对不会。当你在 CryptoOwnBank 点击「Connect Wallet」时，MetaMask 浏览器扩展会打开自己的弹窗——那是 MetaMask 的界面，不是我们的。若是首次连接 MetaMask，它可能要求你创建新钱包或用恢复短语导入现有钱包。整个过程发生在你设备上的 MetaMask 扩展内。你的助记词输入到 MetaMask 自己的安全界面，加密后本地存储在你的电脑上——从不发送给 CryptoOwnBank，从不传到我们的服务器，我们也无法看到。MetaMask 设置完成后，你只需批准连接请求——MetaMask 仅与我们的网站共享你的公开钱包地址，任何人都可以在区块链浏览器上查到同一地址。我们用该地址显示余额、准备未签名交易并展示兑换报价。当你执行兑换或批准代币时，MetaMask 会再次弹出要求确认——只有那时 MetaMask 才在你的设备上用私钥本地签名交易。已签名交易直接上链。CryptoOwnBank 在任何时候都无法访问你的私钥、助记词或签名权限。这与所有合法 DeFi 应用使用的安全模型相同——Uniswap、Aave、OpenSea——它们都以同样方式通过 MetaMask 扩展工作。" },
    "Why does CryptoOwnBank warn me when I paste a seed phrase anywhere on the site?": { q: "为什么我在网站任何地方粘贴助记词时 CryptoOwnBank 会警告我？", a: "因为任何合法的 CryptoOwnBank 流程都绝不需要你在我们的网站上输入助记词。句号。真正的助记词只应出现在：硬件钱包的恢复屏幕、你的钢板，以及（短暂地、仅在浏览器中）SLIP-39 拆分器与 /decrypt 合并器——二者完全在客户端运行且从不传输。<br/><br/>如果你把 12 或 24 个词粘贴到我们网站的搜索栏、地址字段、聊天框或任何其他输入中，页面内警告会立即触发，要求你停止。这能抓住人们被掏空的最常见方式——仿冒我们的钓鱼页面、复制粘贴事故，或听从诈骗「客服」的坏建议。我们宁愿用警告打扰你，也不愿看你因一时困惑而失去一切。" },
    "Is DCA non-custodial? Who holds my funds?": { q: "DCA 是非托管的吗？谁持有我的资金？", a: "100% 非托管。CryptoOwnBank 从不持有、触碰或访问你的资金。DCA 调度器在服务器端运行，并在买入到期时创建待处理的 DEX 报价——但在你亲自于 Xaman 或 LOBSTR 钱包中批准之前，该报价不会提交到区块链。你的私钥从不离开设备。若你不批准待处理执行，什么都不会发生——资金仍留在原处。" },
    "What do I get with Premium?": { q: "Premium 能给我什么？", a: "Premium 解锁完整驾驶舱——拥有你的加密资产，从一个界面管理，保留全部收益。XRPL DEX 交易（44 个交易对，含 Quick Swap 与 Advanced 订单簿）、Stellar DEX 交易（13 个交易对）、无限交易所连接、全部 32+ 链上无限区块链地址、完整交易历史、CSV 导入、无限价格提醒、含个性化收益优化的完整 Recommendations Hub（呈现你否则会错过的机会）、对比银行利率与链上收益的 Statement Insights、带自定义阈值的扩展 Whale Alerts、含全部指标与最长 10 年图表数据的 Technical Analysis，以及呈现匹配你所持资产文章的个性化 Crypto News。选择月付（$29/mo）或年付（$199/yr）还可解锁完整税务报告。安全级别由你选择——冷钱包、热钱包、硬件或手机签名。" },
    "Why should I upgrade to Premium?": { q: "我为什么应该升级到 Premium？", a: "如果你的加密资产分散在多个交易所、钱包和 DeFi 协议中，Premium 给你一个驾驶舱看清一切。不必分别登录 Binance、Coinbase、Ledger Live 和 Yahoo Finance，你可在单一仪表盘中看到跨 32+ 区块链的完整投资组合、带链上与托管清晰度的个性化收益建议、税务负债与收益。Recommendations Hub 准确显示你错过了多少收益，以及哪些链上机会匹配你已持有的资产。" },
    "Can I pay for Premium with crypto?": { q: "我可以用加密货币支付 Premium 吗？", a: "可以——这样做可节省 10%。我们接受 25 条区块链上的加密货币：XRP、RLUSD、BTC、ETH、SOL、XLM、DOGE、LTC、ADA、AVAX、ALGO、ATOM、TRX、HBAR、DOT、VET、TON、MATIC、CRO、XDC、DGB、CSPR、CKB、ZIL 和 XVG。Premium 降至 $26.10/mo 或 $179.10/yr，Pro 降至 $89.10/mo 或 $719.10/yr——均为刷卡价格的九折。前往 Settings → Subscription → Pay with Crypto，选择你的链，我们会显示确切金额（通过 CoinGecko 实时定价）与收款钱包地址。对于 XRP 和 RLUSD，你还会获得唯一 destination tag 以匹配付款。我们的系统在链上验证付款并立即激活订阅。无需 KYC、银行账户或信用卡——只需发送加密货币即可升级。也可通过 Stripe 刷卡作为备选。" },
    "Can I cancel Premium anytime?": { q: "我可以随时取消 Premium 吗？", a: "可以。你可以随时取消订阅。你将保留 Premium 访问权限直至当前计费周期结束。无罚款，无追问。" },
    "What happens if I cancel my subscription or leave CryptoOwnBank?": { q: "如果我取消订阅或离开 CryptoOwnBank 会怎样？", a: "你的加密资产不会发生任何事。这正是重点。因为 CryptoOwnBank 是非托管的，我们从不持有你的资产。若你取消 Premium、降级到 Free 或完全离开——加密资产仍在你的钱包中，Soil 金库仓位仍在赚取收益，信任线仍然有效，你可通过 Xaman、Ledger 或任何其他 XRPL 兼容工具访问一切。你支付的是仪表盘、分析、Recommendations Hub 与交易工具——不是资产托管。你可以离开我们并仍完全掌控。（但我们希望你不想离开。）" },
    "Why do BTC, ETH, SOL, XRP, and RLUSD get a bigger discount?": { q: "为什么 BTC、ETH、SOL、XRP 和 RLUSD 能获得更大折扣？", a: "我们称这五种为我们的 <strong>House Tier</strong>——用其中任何一种支付订阅、附加服务或 Legacy Lifetime，即可获得与所有支持加密货币相同的统一 <strong>10% 链上折扣</strong>。House Tier 是偏好币种标识，不是额外折扣。原因是诚实的国库对齐：BTC、ETH 和 SOL 是我们乐于持有的蓝筹资产（它们往往随时间升值，以不会升值的美元计价），而 XRP/RLUSD 是我们的主链——RLUSD 实际上资助向会员支付 5–8% APR 的 Soil Protocol 金库。当你用这些资产向我们付款时，你实际上是在为我们想要增长的国库做贡献，而不是我们必须转换的 Stripe 出款。我们把节省返还给你，体现为更大折扣。<br/><br/>其他 20 种支持的加密货币（DOGE、LTC、ADA、AVAX、ATOM、XLM、TON、MATIC 等）仍可获得相对刷卡支付的标准 10% 链上折扣——绝对欢迎，只是不属于 house tier。<br/><br/><strong>Founder Badge：</strong>若你用任何 House Tier 币种购买 <strong>Legacy Plan Lifetime</strong>，账户会获得永久可见的 Founding Member 徽章，显示你支付的币种与月份。这是我们感谢在第一天就把真正的比特币、以太坊、Solana 或 XRP 投入平台的会员的方式。" },
    "How safe is my principal?": { q: "我的本金有多安全？", a: "你的本金通过两种方式受到保护：1）非托管设计——密钥从不离开你的冷钱包。2）Soil 金库由真实世界资产（国债、信贷基金）支撑，具备机构级承保。Soil 公布固定目标 APR，但回报不获保证——加密/区块链始终带有风险（智能合约漏洞、协议变更、市场事件、交易对手/RWA 风险）。务必自行研究（DYOR）。" },
    "Can I use Soil vaults without Premium?": { q: "没有 Premium 可以使用 Soil 金库吗？", a: "可以。连接 XRPL 钱包、存入 <a href=\"/ownbank/vaults\" class=\"text-[#00A4E4] underline hover:no-underline\">Soil 金库</a>，以及 <a href=\"/ownbank/withdraw\" class=\"text-[#00A4E4] underline hover:no-underline\">通过 Soil 取出</a> 全部免费。Premium 增加用于 RLUSD 自动兑换为 XRP 的 DCA。" },
  },
};

export function localizeFaqGroups(lang: string): FaqGroup[] {
  if (lang === "en" || !(lang in faqP0Translations)) return faqGroups;
  const pack = faqP0Translations[lang as FaqP0Lang];
  return faqGroups.map((group) => ({
    ...group,
    items: group.items.map((it) => {
      const t = pack[it.q];
      return t ? { q: t.q, a: t.a } : it;
    }),
  }));
}
